(window.GIM_TS=window.GIM_TS||{})["Gittin.0"]={"from":0,"a":[["שליח \u0003המביא\u0004 מן הבעל לאשתו \u0003גט\u0004 גירושין, ובא \u0003ממדינת הים\u0004 (חוץ לארץ) לארץ ישראל, \u0003צריך שיאמר\u0004 בשעת מסירת הגט: \u0003\"בפני נכתב\u0004 גט זה, \u0003ובפני נחתם\".\u0004","\u0003רבן גמליאל אומר: אף המביא\u0004 גט \u0003מן הרקם ומן החגר\u0004 שהם מקומות הנמצאים בסוף תחומי ארץ ישראל, צריך לומר \"בפני נכתב ובפני נחתם\". \u0003ר' אליעזר אומר: אפילו\u0004 המביא גט \u0003מכפר לודים ללוד,\u0004 למרות שהם מקומות סמוכים זה לזה, מכל מקום כיון שכפר לודים אינו שייך למקום היישוב היהודי העיקרי בארץ ישראל — צריך לומר דבר זה.","\u0003וחכמים אומרים: אינו צריך שיאמר \"בפני נכתב ובפני נחתם\" אלא המביא ממדינת הים\u0004 לארץ ישראל. \u0003ו\u0004כן \u0003המוליך\u0004 גט מארץ ישראל למדינת הים. \u0003ו\u0004כן \u0003המביא\u0004 גט \u0003ממדינה למדינה במדינת הים,\u0004 אף הוא \u0003צריך שיאמר \"בפני נכתב ובפני נחתם\". רבן שמעון בן גמליאל אומר:\u0004 לאו דווקא ממדינה למדינה, אלא \u0003אפילו מהגמוניא להגמוניא\u0004 (ממחוז למחוז) באותה מדינה.","\u0003ר' יהודה אומר:\u0004 לגבי גבולות ארץ ישראל, \u0003מרקם\u0004 ו\u0003ל\u0004צד \u0003מזרח\u0004 ממנה הריהו נחשב כמדינת הים, \u0003ורקם\u0004 עצמה — \u0003כמזרח\u0004 ארץ ישראל, כלומר, כחוץ לארץ. \u0003מאשקלון לדרום ואשקלון\u0004 עצמה — \u0003כדרום,\u0004 וכן \u0003מעכו לצפון, ועכו\u0004 עצמה — \u0003כצפון. ר' מאיר אומר: עכו\u0004 — \u0003כארץ ישראל ל\u0004ענין \u0003גיטין.\u0004","\u0003המביא גט\u0004 ממקום למקום \u0003בארץ ישראל\u0004 — \u0003אינו צריך שיאמר \"בפני נכתב ובפני נחתם\", ו\u0004בכל מקרה, \u0003אם יש עליו עוררים,\u0004 כלומר, שבא הבעל ומערער על כשרות הגט וטוען שהוא מזוייף — \u0003יתקיים\u0004 הגט \u0003בחותמיו,\u0004 כלומר, יבדקו את חתימת העדים, ויאשרו ויקיימו אותו על פי חתימתם זו.","שנינו במשנה שהמביא גט ממדינת הים צריך שיאמר \"בפני נכתב ופני נחתם\", ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003רבה אמר:\u0004"],["\u0003לפי שאין\u0004 בני מדינת הים \u0003בקיאין\u0004 בדיני כתיבת גט \u0003לשמה.\u0004 שלא די שהגט כתוב כראוי אלא צריך שייכתב לשם האיש והאשה ששמם מופיע בו, ומשום כך כאשר העד צריך לבוא בפני בית דין ולהעיד \"בפני נכתב ובפני נחתם\", מבררים גם אם היו הכתיבה והחתימה לשמה.","\u0003רבא אמר\u0004 טעם אחר: \u0003לפי שאין עדים מצויין לקיימו.\u0004 שמקום כתיבת הגט רחוק, וייתכן שיבוא הבעל ויערער ויאמר שמזוייף הוא והוא לא כתב גט זה מעולם, ומשום כך צריך השליח לומר שבפניו נחתם הגט, ומאמינים לו.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 במקרה \u0003דאתיוהו בי תרי\u0004 \u0005[שהביאוהו,\u0006 את הגט, \u0005שנים],\u0006 שבמקרה זה לשיטת רבא אין עוד מקום לערעור הבעל, כי שני עדים מצויים כאן לקיים את הגט אם יהיה עליו ערעור. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש ביניהם הבדל אחר: כשמביא אותו \u0003ממדינה למדינה\u0004 \u0003בארץ ישראל,\u0004 ולכן אין מקום לחשש זה שלא נכתב הגט לשמה, שלגבי הצורך של כתיבה לשמה — הרי בקיאים בכך בכל ארץ ישראל, אבל עדים אינם מצויים לקיים את הגט.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 כאשר מביא את הגט \u0003באותה מדינה במדינת הים,\u0004 שלדעת רבה שהחשש הוא משום שאין בקיאים לשמה — צריך לומר כמו כן שם שמאחר שאין בקיאים, אף שהוא באותה מדינה, מכל מקום צריכים לקיימו, ולדעת רבא שהטעם הוא משום שאין עדים מצויים, הרי באותה מדינה עדים מצויים לקיימו.","ושואלים: \u0003ול\u0004דעת \u0003רבה\u0004 ש\u0003אמר\u0004 שהטעם הוא \u0003לפי שאין בקיאין לשמה\u0004 — \u0003ליבעי תרי\u0004 \u0005[שיצטרכו שני\u0006 עדים\u0005]\u0006 שיעידו על כך, \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 על \u0003כל עדיות שבתורה!\u0004 ומשיבים: בענין זה אפשר לומר כי \u0003עד אחד נאמן באיסורין,\u0004 כי אם יש בפנינו דבר שלא ברור אם הוא היה אסור או מותר, עדותו של עד אחד מספיקה כדי להתירו.","ותוהים: \u0003אימור דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 ש\u0003עד אחד נאמן באיסורין,\u0004 אימתי — \u0003כגון\u0004 שהיתה לפנינו \u0003חתיכה\u0004 ש\u0003ספק\u0004 אם היא \u0003של חלב\u0004 שאסור באכילה, \u0003ספק של שומן\u0004 המותר באכילה, ש\u0003לא איתחזק\u0004 \u0005[הוחזק]\u0006 מקודם \u0003איסורא\u0004 \u0005[האיסור]\u0006 בדבר, וכיון שיש ספק, ובא עד אחד ואמר שהיא של שומן — מאמינים לו.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דאיתחזק איסורא\u0004 \u0005[שהוחזק\u0006 כבר \u0005האיסור]\u0006 של \u0003אשת איש,\u0004 שכל עוד לא ניתן לה גט היא בחזקת אשת איש, אם כן \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003דבר שבערוה, ו\u0004כלל הוא: \u0003אין\u0004 עדות ב\u0003דבר שבערוה פחות משנים!\u0004","ומשיבים: באמת חשש זה שאמר רבה הוא מעיקרו רק חשש רחוק, כי \u0003רוב\u0004 בני אדם \u0003בקיאין הן\u0004 בדין כתיבה לשמה. \u0003ואפילו ל\u0004דעת \u0003ר' מאיר דחייש למיעוטא\u0004 \u0005[שחושש\u0006 גם \u0005למיעוט]\u0006 בדברים שבערוה ואינו הולך בהם אחר הרוב, ולכאורה צריך היה לשיטתו להחמיר בדבר, מכל מקום יש כאן יותר מאשר רוב, כי \u0003סתם ספרי דדייני\u0004 \u0005[סופרי הדיינים]\u0006 הכותבים את הגיטין \u0003מיגמר גמירי\u0004 \u0005[למודים\u0006 הם\u0005]\u0006 בהלכה, ויודעים שצריך שתהא בהם כתיבה לשמה, ולמיעוט קטן כל כך של סופרים שאינם למודים בדבר אין לחשוש מעיקר הדין, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003הוא דאצרוך\u0004 \u0005[שהצריכו]\u0006 מפני חשש זה עדות על הדבר. \u0003והכא\u0004 \u0005[וכאן]\u0006 בעדות זו"],["\u0003משום עיגונא\u0004 \u0005[עיגון]\u0006 \u0003אקילו\u0004 \u0005[הקלו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 שנאמין לשליח המביא את הגט, אף שהוא אחד, כדי שלא להביא לכך שנשים תהיינה עגונות בגלל מחסור בשליחים.","ותוהים: וכי \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003קולא\u0004 \u0005[להקל]\u0006 \u0003הוא?\u0004 הלא \u0003חומרא\u0004 \u0005[להחמיר]\u0006 \u0003הוא, דאי מצרכת ליה תרי\u0004 \u0005[שאם אתה מצריך לו,\u0006 לגט, \u0005שנים]\u0006 שיעידו עליו — \u0003לא אתי\u0004 \u0005[יבוא]\u0006 \u0003בעל מערער ופסיל ליה\u0004 \u0005[\u0006ו\u0005יערער ויפסול אותו],\u0006 שהרי לא יתקבלו דבריו, ועדותו בטילה כנגד שני עדים. אבל אם מביא רק שליח \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003אתי\u0004 \u0005[יבוא]\u0006 ה\u0003בעל ומערער ופסיל ליה\u0004 \u0005[ויערער ויפסול אותו]!\u0006","ומשיבים: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בפני כמה\u0004 אנשים השליח המביא את הגט \u0003נותנו לה,\u0004 לאשה? \u0003ר' יוחנן ור' חנינא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: בפני שנים, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: בפני שלשה,\u0004 שיודע השליח שאי אפשר לעשות זאת בינו לבינה, אלא צריך שיהיה מעין בית דין בדבר, ולכן \u0003מעיקרא מידק דייק\u0004 \u0005[מתחילה מדקדק],\u0006 מברר היטב השליח בדבר \u0003ולא אתי לאורועי נפשיה\u0004 \u0005[יבוא להרע עצמו]\u0006 בכך שהביא גט פסול.","ושואלים: \u0003ול\u0004דעת \u0003רבא\u0004 ש\u0003אמר\u0004 שצריך השליח לומר \"בפני נכתב ובפני נחתם\" \u0003לפי שאין עדים מצויין לקיימו\u0004 — אם כן \u0003ליבעי תרי\u0004 \u0005[שיצטרכו שנים],\u0006 \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 החל על \u0003קיום שטרות דעלמא\u0004 \u0005[בכלל]\u0006 שמקיימים את השטר רק על פי שני עדים! ומשיבים: \u0003עד אחד נאמן באיסורין.\u0004","ומקשים: \u0003אימר דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 ש\u0003עד אחד נאמן באיסורין,\u0004 מתי — \u0003כגון חתיכה\u0004 שהיא \u0003ספק של חלב\u0004 האסור באכילה, \u0003ספק של שומן\u0004 המותר באכילה, ש\u0003לא איתחזק איסורא\u0004 \u0005[הוחזק האיסור\u0006 קודם לכן\u0005],\u0006 \u0003אבל הכא איתחזק איסורא\u0004 \u0005[כאן\u0006 שכבר \u0005הוחזק האיסור]\u0006 של \u0003אשת איש\u0004 לגבי אשה זו, ואם כן \u0003הוי\u0004 \u0005[הריהי]\u0006 עדות על \u0003דבר שבערוה, ואין\u0004 עדות בענין \u0003דבר שבערוה פחות משנים!\u0004","ומשיבים: \u0003בדין הוא\u0004 (מן הדין היה) ש\u0003בקיום שטרות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליבעי\u0004 \u0005[יצטרכו]\u0006 שני עדים, ו\u0003כ\u0004דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: עדים החתומים על השטר\u0004 — \u0003נעשו כמי שנחקרה עדותן בבית דין.\u0004 ובעצם היינו צריכים לסמוך על השטר כמות שהוא, \u0003ו\u0004אולם \u0003רבנן הוא דאצרוך\u0004 \u0005[חכמים הם שהצריכו]\u0006 שיחקרו בית דין את עדותם, ויקיימו את השטר בעדים. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003משום\u0004 חשש \u0003עיגונא\u0004 \u0005[לעיגון]\u0006 האשה \u0003אקילו\u0004 \u0005[הקילו]\u0006 \u0003בה רבנן\u0004 \u0005[חכמים]\u0006 לקיים את השטר בעדות השליח לבדו.","ותוהים: \u0003האי\u0004 \u0005[\u0006וכי דבר \u0005זה]\u0006 \u0003קולא\u0004 \u0005[להקל]\u0006 \u0003הוא?\u0004 הלא \u0003חומרא\u0004 \u0005[להחמיר]\u0006 \u0003הוא! דאי מצרכת ליה תרי\u0004 \u0005[שאם מצריך אתה לו,\u0006 לגט, \u0005שנים]\u0006 שיעידו עליו — \u0003לא אתי\u0004 \u0005[יבוא]\u0006 ה\u0003בעל מערער ופסיל ליה\u0004 \u0005[\u0006ו\u0005יערער ויפסול אותו],\u0006 אבל אם יש רק עד \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003אתי\u0004 \u0005[יבוא]\u0006 \u0003בעל ומערער ופסיל ליה\u0004 \u0005[ויערער ויפסול אותו]!\u0006 ומשיבים: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בפני כמה נותנו לה? ר' יוחנן ור' חנינא\u0004 נחלקו בזה, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: בפני שנים, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: בפני שלשה,\u0004 לכן \u0003מעיקרא מידק דייק\u0004 \u0005[מתחילה מדקדק\u0006 השליח בדבר\u0005]\u0006 \u0003ולא אתי לאורועי נפשיה\u0004 \u0005[יבוא להרע\u0006 את \u0005עצמו]\u0006 בהבאת גט פסול.","לאחר בירור יסודי זה, באים לדון בעצם השיטות. ושואלים: \u0003ורבא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבה\u0004 שצריך השליח לומר \"בפני נכתב ובפני נחתם\" משום חשש שנכתב הגט שלא לשמה? ומשיבים, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה שהשליח צריך לומר \u0003\"בפני נכתב לשמה, בפני נחתם לשמה\"?\u0004 וכיון שלא נאמר שצריך להעיד שהיה זה \"לשמה\" משמע שלא מפני חשש זה תיקנו חכמים תקנה זו.","ושואלים מצד אחר: \u0003ורבה,\u0004 מה הוא משיב לטענה זו? ומשיבים: \u0003בדין הוא\u0004 (מן הדין היה) \u0003דליתני הכי\u0004 \u0005[שישנה כך],\u0006 \u0003אלא\u0004 לא חייבו חכמים לומר כן כיון \u0003דאי מפשת ליה דיבורא\u0004 \u0005[שאם אתה מרבה לו\u0006 — לשליח \u0005בדיבור]\u0006 שאתה מחייבו לומר בנוסח רחב זה — \u0003אתי למגזייה\u0004 \u0005[\u0006הריהו עלול \u0005לבוא לחותכו],\u0006 לקצר את דיבורו, ולא יאמר את כל מה שהוא צריך להעיד ויגרום בכך לפסול את הגט.","ושואלים: \u0003השתא נמי אתי למגזייה\u0004 \u0005[עכשיו\u0006 באופן אמירה זה \u0005גם כן יבוא לחתוך,\u0006 לקצר \u0005אותו]\u0006 שלא יאמר \"בפני נכתב\" או \"בפני נחתם\", ומשיבים: \u0003חדא מתלת גאיז\u0004 \u0005[\u0006דבר \u0005אחד מ\u0006תוך \u0005שלושה עשוי\u0006 הוא \u0005לחתוך,\u0006 להשמיט\u0005],\u0006 \u0003חדא מתרתי לא גאיז\u0004 \u0005[אחד משנים אינו חותך],\u0006 ולכן בזה שמצריכים אותו לומר \"בפני נכתב\" ו\"בפני נחתם\" לא יקצר בזה.","ושואלים: \u0003ורבה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבא\u0004 שטעמה של התקנה משום שאין עדים מצויים לקיימו? ומשיבים, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003אם כן\u0004 שטעם התקנה הוא כדברי רבא די היה בכך ש\u0003ניתני\u0004 \u0005[ישנה]\u0006 \u0003\"בפני נחתם\" ותו לא\u0004 \u0005[ולא עוד],\u0006 שהרי בכך העד מאשר את חתימת העדים שבשטר, \u0003\"בפני נכתב\" למה לי\u0004 לומר? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהחשש שביסוד התקנה הוא משום ש\u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שייכתב הגט לשמה.","ושואלים: \u0003ורבא,\u0004 מה הוא עונה לטענה זו? ומשיבים: \u0003בדין הוא דליתני הכי\u0004 \u0005[שישנה כך],\u0006 \u0003אלא\u0004 ש\u0003אם כן,\u0004 אם היה אומר רק \"בפני נחתם\", \u0003אתי לאיחלופי\u0004 \u0005[יבואו\u0006 אנשים \u0005להחליף]\u0006 את הדבר \u0003בקיום שטרות דעלמא\u0004 \u0005[בכלל]\u0006 ויחשבו שגם שטר אחר אפשר לקיימו \u0003ב\u0004עדות של \u0003עד אחד,\u0004 ולכן הוסיפו חכמים שיאמר השליח נוסח \"בפני נכתב\" שאיננו נאמר בדרך כלל בקיום שטרות.","\u0003ורבה\u0004 משיב לטענה זו: אין חשש שיבואו להחליף בין קיום גט לבין קיום שטרות, שכן \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 כלל הדברים? הלא \u0003התם\u0004 \u0005[שם]\u0006 בקיום שטרות צריכים העדים לומר רק \u0003\"ידעינן\"\u0004 \u0005[\"יודעים אנו\"]\u0006 שזו חתימת העדים, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בגט הוא אומר \u0003\"בפני\u0004 נחתם","\u0003\".\u0004 והבדל נוסף: \u0003התם\u0004 \u0005[שם]\u0006 בקיום שטרות \u0003אשה לא מהימנא\u0004 \u0005[נאמנת],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בגט \u0003אשה מהימנא\u0004 \u0005[נאמנת]\u0006 להביא גט ולומר שבפניה נכתב ונחתם. והבדל נוסף: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בעל דבר\u0004 (שיש לו ענין בקיום השטר) \u0003לא מהימן\u0004 \u0005[נאמן]\u0006 להעיד על כשרות השטר, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בגט \u0003בעל דבר מהימן\u0004 \u0005[נאמן],\u0006 שגם האשה עצמה המביאה את גיטה שלה יכולה להעיד שהדבר נעשה כראוי.","\u0003ורבא\u0004 מה הוא משיב על טענה זו? \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 בתשובה על טענה זו: \u0003אטו הכא כי אמרי \"ידעינן\" מי לא מהימני\u0004 \u0005[וכי כאן\u0006 בגט \u0005כאשר\u0006 עדי הקיום \u0005אומרים\u0006 בלשון \u0005\"יודעים אנו\" האם אינם נאמנים]?\u0006 \u0003וכיון דכי אמרי \"ידעינן\" מהימני\u0004 \u0005[שכאשר\u0006 הם \u0005אומרים \"יודעים אנו\"\u0006 הרי הם \u0005נאמנים],\u0006 אם כן \u0003אתי לאיחלופי\u0004 \u0005[יבואו להחליף]\u0006 את הדבר \u0003בקיום שטרות דעלמא\u0004 \u0005[בכלל],\u0006 לעשותו \u0003בעד אחד.\u0004","ושואלים: \u0003ול\u0004דעת \u0003רבה\u0004 ש\u0003אמר\u0004 שטעם אמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין בקיאין לשמה, מאן האי\u0004 \u0005[מיהו זה]\u0006 ה\u0003תנא דבעי\u0004 \u0005[שמצריך]\u0006 שתהיה \u0003כתיבה\u0004 של הגט \u0003לשמה,\u0004 \u0003ובעי\u0004 \u0005[ומצריך]\u0006 גם כן"],["שתהא גם \u0003חתימה לשמה?\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' מאיר\u0004 היא, הלא \u0003חתימה\u0004 לשמה \u0003בעי\u0004 \u0005[צריך],\u0006 \u0003כתיבה לא בעי\u0004 \u0005[צריך]\u0006 שתהיה לשמה! \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין כותבין\u0004 גט \u0003ב\u0004עודו \u0003מחובר לקרקע,\u0004 ואולם אם \u0003כתבו על המחובר לקרקע\u0004 ואחר כך \u0003תלשו, חתמו ונתנו לה\u0004 — \u0003כשר!\u0004 משמע שעיקרו של הגט הוא בחתימה, ודבר זה הוא סתם משנה, שהיא כשיטת ר' מאיר.","\u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' אלעזר\u0004 החולק עליו, הלא לשיטתו \u0003כתיבה בעי\u0004 \u0005[צריך\u0006 הוא\u0005]\u0006 שתהיה לשמה, אבל \u0003חתימה לא בעי\u0004 \u0005[צריך]\u0006 שתהא לשמה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]!\u0006 כי \u0003לעולם\u0004 שיטת \u0003ר' אלעזר היא,\u0004 \u0003ו\u0004אולם \u0003כי לא בעי\u0004 \u0005[כאשר אין צריך]\u0006 ל\u0003ר' אלעזר\u0004 שתהא \u0003חתימה לשמה\u0004 — הרי זה \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 אבל \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 — \u0003בעי\u0004 \u0005[צריך].\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 כאשר מנו חכמים \u0003שלשה גיטין\u0004 שכשרים מן התורה אבל \u0003פסולין דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ולא בעי\u0004 \u0005[צריך]\u0006 ל\u0003ר' אלעזר\u0004 שתהא \u0003חתימה לשמה\u0004.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה גיטין פסולין\u0004 הם לכתחילה, \u0003ו\u0004אולם \u0003אם ניסת\u0004 (נישאה) האשה לאיש אחר על סמך גט זה — \u0003הולד\u0004 הנולד מנישואים אלה \u0003כשר,\u0004 ואין אומרים שהיא נחשבת כאשת איש שנבעלה לאחר, והוולד פסול. ואלו הם: גט ש\u0003כתב\u0004 הבעל \u0003בכתב ידו\u0004 \u0003ואין עליו\u0004 חתימת \u0003עדים\u0004 כלל, או גט ש\u0003יש עליו\u0004 חתימת \u0003עדים ואין\u0004 מצוי \u0003בו זמן\u0004 כתיבתו, או \u0003יש בו זמן ואין בו אלא עד אחד\u0004 — \u0003הרי אלו שלשה גיטין פסולין, ואם ניסת\u0004 — \u0003הולד כשר.\u0004","\u0003ר' אלעזר אומר: אף על פי שאין עליו\u0004 חתימת \u0003עדים אלא שנתנו לה בפני עדים\u0004 — הרי זה גט \u0003כשר, ו\u0004האשה יכולה מכח גט זה להיות \u0003גובה מנכסים משועבדים\u0004 של הבעל את שיעור כתובתה, \u0003ש\u0004לדעתו \u0003אין העדים חותמים על הגט אלא מפני תיקון העולם,\u0004 שאם לא יהיו עדים חתומים על הגט, יוכל הבעל לבוא ולערער בכל עת שלא הוא כתבו, ולכן באים העדים לאשר שאכן נעשה הגט כתיקונו. ומכל מקום רואים מכאן שלדעת ר' אלעזר אין חתימת העדים חלק מהותי מן הגט, וממילא אינה צריכה להיות לשמה, אפילו לדברי סופרים.","\u0003ואלא\u0004 תאמר ששיטת משנתנו שיטת \u0003ר' מאיר היא, וכי לא בעי\u0004 \u0005[וכאשר אין צריך]\u0006 לדעת \u0003ר' מאיר\u0004 שתהא \u0003כתיבה לשמה\u0004 — הרי זה \u0003מדאורייתא\u0004 \u0005[מדברי תורה],\u0006 אבל \u0003מדרבנן בעי\u0004 \u0005[מדברי סופרים צריך],\u0006 גם על כך יש להקשות: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן, אומר היה ר' מאיר:\u0004 גט אינו צריך כתיבה לשמה, עד כדי כך ש\u0003אפילו\u0004 גט ש\u0003מצאו באשפה\u0004 והיו שמות הבעל והאשה שבגט כשמו ושם אשתו,"],["\u0003וחתמו ונתנו לה\u0004 לאשתו — הרי זה גט \u0003כשר! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמה שאמר רב נחמן \u0003אנן מדאורייתא קא מתנינן לה\u0004 \u0005[אנו מדין תורה שונים אנו אותה]\u0006 לשיטת ר' מאיר, אבל מדברי סופרים סבור הוא שצריך כתיבה לשמה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003\"אומר היה ר' מאיר דבר תורה\u0004 מצאו באשפה\" וכו' \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לרב נחמן לומר!","\u0003אלא,\u0004 יש לחזור מהתירוץ הקודם ולומר: \u0003לעולם\u0004 משנתנו שיטת \u0003ר' אלעזר היא, וכי לא בעי\u0004 \u0005[וכאשר אין צריך]\u0006 לדעת \u0003ר' אלעזר\u0004 שתהא \u0003חתימה\u0004 לשמה — הרי זה \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003עדים כלל\u0004 על הגט, אבל \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003עדים\u0004 על הגט — \u0003בעי\u0004 \u0005[צריך]\u0006 שתהיה גם חתימתם לשמה. וראיה לדבר ממה ש\u0003אמר ר' אבא: מודה ר' אלעזר, ב\u0004שטר ה\u0003מזוייף מתוכו\u0004 שחתמו בו עדים פסולים \u0003שהוא פסול.\u0004 ורואים איפוא שלדעת ר' אלעזר למרות שהחתימה כשלעצמה אינה מעכבת, בכל זאת אם יש בגט חתימת עדים — צריכה החתימה להיעשות כראוי, ואם לא נעשתה כראוי היא פוסלת את הגט.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]?\u0006 — כשיטה שלישית, כשיטת \u0003ר' יהודה היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה פוסל, עד שתהא כתיבתו וחתימתו\u0004 של הגט \u0003בתלוש,\u0004 כלומר, בכשרות. ולפי זה יש צורך גם בכתיבה וגם בחתימה לשמה.","ושואלים: \u0003ומעיקרא מאי טעמא\u0004 \u0005[ומתחילה מה טעם]\u0006 \u0003לא מוקמינן לה\u0004 \u0005[העמדנו,\u0006 הסברנו, \u0005אותה]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה?\u0004 שהרי משנה מפורשת היא, והיא נראית בפשטות כשיטה זו של משנתנו שחיפשנו לה מקור!","ומשיבים: \u0003מהדרינן\u0004 \u0005[מחזרים,\u0006 משתדלים \u0005אנו]\u0006 להסביר את המשנה על דעת \u0003ר' מאיר,\u0004 כיון ש\u0003סתם מתניתין\u0004 \u0005[משנתנו]\u0006 שיטת \u0003ר' מאיר\u0004 היא. ומצד שני \u0003מהדרינן\u0004 \u0005[מחזרים,\u0006 משתדלים \u0005אנו]\u0006 להעמידה כשיטת \u0003ר' אלעזר, דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 כי \u0003הילכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 \u0003בגיטין,\u0004 ומשום כך ניסינו תחילה להעמיד את משנתנו לפי שיטת אחד מהתנאים הללו, ולא כשיטת ר' יהודה.","וממשיכים לבאר את משנתנו לאור מחלוקת רבה ורבא. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003רבן גמליאל אומר: אף המביא\u0004 גט \u0003מן הרקם ומן החגר\u0004 צריך שיאמר \"בפני נכתב ובפני נחתם\". \u0003ר' אליעזר אומר: אפילו מכפר לודים ללוד. ואמר אביי\u0004 בהסברת הדברים: \u0003בעיירות\u0004 שאינן בארץ ישראל עצמה, אלא \u0003הסמוכות לארץ ישראל ומובלעות בתחום ארץ ישראל עסקינן\u0004 \u0005[עוסקים אנו],\u0006","\u0003ואמר רבה בר בר חנה\u0004 שבא מארץ ישראל: \u0003לדידי חזי לי ההוא אתרא\u0004 \u0005[אני עצמי ראיתי\u0006 את \u0005המקום הזה]\u0006 שבין כפר לודים ללוד, \u0003והוי\u0004 \u0005[והיה]\u0006 מרחקו \u0003כ\u0004מו \u0003מ\u0004המקום \u0003בי כובי לפומבדיתא\u0004 שהוא מרחק קטן.","ונדייק: \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנתנו \u0003סבר\u0004 \u0005[סבור]:\u0006 כי \u0003הני\u0004 \u0005[\u0006במקומות \u0005הללו]\u0006 \u0003לא צריך\u0004 השליח להעיד שנכתב ונחתם הגט לשמה. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006עיקרון \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 שטעם אמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין בקיאין לשמה, והני גמירי\u0004 \u0005[ו\u0006תושבי מקומות \u0005אלה למודים]\u0006 הם בדבר, כי הם סמוכים לארץ ישראל, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן גמליאל, \u0005סבור]\u0006 שהטעם הוא \u0003לפי שאין עדים מצויין לקיימו, והני נמי לא שכיחי\u0004 \u0005[ו\u0006תושבי מקומות \u0005אלה גם כן אינם מצויים]\u0006 משום שהם שוכנים מעבר לגבול, ויש קשיים בהבאת עדים ממקום למקום?","ודוחים: \u0003לא,\u0004 אין להוכיח שהדבר שנוי במחלוקת תנאים, ולגבי הקשיים \u0003רבה מתרץ\u0004 (מיישב, מסביר) \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים: \u0003רבה\u0004 היה \u0003מתרץ\u0004 דבר זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 הטעם הוא \u0003לפי שאין בקיאין לשמה, והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חלוקים],\u0006 ה\u0003תנא קמא סבר:\u0004 \u0005[הראשון סבור]\u0006 כי \u0003הני\u0004 \u0005[\u0006תושבי ערים \u0005אלה]\u0006 \u0003כיון\u0004 ש\u0003סמוכות\u0004 ערים אלה לארץ ישראל \u0003מיגמר גמירי\u0004 \u0005[למודים\u0006 הם\u0005],\u0006","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן גמליאל למימר\u0004 \u0005[לומר]\u0006 כך: אף שתושבי אותן ערים שהן \u0003מובלעות\u0004 בתחום ארץ ישראל \u0003גמירי\u0004 \u0005[למודים]\u0006 בדבר, מכל מקום תושבי אלה שהן \u0003סמוכות\u0004 בלבד \u0003לא גמירי\u0004 \u0005[אינם למודים]\u0006 בדבר. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]\u0006 כשאמר שאף מכפר לודים ללוד, ש\u0003מובלעות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שאין לסמוך על בקיאותם, ש\u0003לא תחלוק במדינת הים,\u0004 וההנחה היא שארץ ישראל יש לה דין לעצמה, וכל מקום שאינו ממש חלק מן היישוב היהודי של ארץ ישראל, יש לו דיני חוץ לארץ.","ומצד שני \u0003רבא מתרץ\u0004 \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 הטעם לאמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין עדים מצויין לקיימו, ו\u0004ה\u0003תנא קמא סבר:\u0004 \u0005[הראשון סבור]\u0006 כי \u0003הני\u0004 \u0005[\u0006תושבי ערים \u0005אלה]\u0006 \u0003כיון\u0004 ש\u0003סמוכות מישכח שכיחי\u0004 \u0005[מצויים\u0006 הם\u0005],\u0006","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן גמליאל למימר\u0004 \u0005[לומר]\u0006 כי תושבי הערים ה\u0003מובלעות שכיחי\u0004 \u0005[מצויים],\u0006 ואילו תושבי הערים ה\u0003סמוכות\u0004 בלבד \u0003לא שכיחי\u0004 \u0005[מצויים],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]\u0006 ש\u0003מובלעות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נחשבות כארץ ישראל לענין זה, ואף על פי שהמקום קרוב וסמוך לארץ ישראל, \u0003שלא תחלוק במדינת הים.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003וחכמים אומרים: אינו צריך שיאמר \"בפני נכתב ובפני נחתם\" אלא המביא\u0004 גט \u0003ממדינת הים, והמוליך\u0004 מארץ ישראל למדינת הים. ונדייק: \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של משנתנו \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003מוליך\u0004 למדינת הים \u0003לא צריך\u0004 לומר. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 שהטעם של העדות הוא \u0003לפי שאין בקיאין לשמה,\u0004"],["\u0003והני גמירי\u0004 \u0005[ואלה למודים]\u0006 בדבר, שהרי הגט נשלח מארץ ישראל, וגט שנכתב שם ודאי נעשה בכשרות. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]\u0006 בטעם העדות \u0003לפי שאין עדים מצויין לקיימו, והני\u0004 \u0005[ואלה]\u0006 ההולכים מארץ ישראל למדינת הים \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא שכיחי\u0004 \u0005[מצויים]?\u0006","ודוחים: אין להוכיח מכאן, אלא \u0003רבה מתרץ\u0004 (מיישב, מסביר) את הדברים \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ורבא מתרץ\u0004 את הדברים \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 \u0003רבה מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 הטעם הוא \u0003לפי שאין בקיאין לשמה, והכא\u0004 \u0005[וכאן]\u0006 \u0003בגזירת מוליך אטו\u0004 \u0005[משום]\u0006 \u0003מביא קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כיצד?","— שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 \u0003מוליך אטו\u0004 \u0005[משום]\u0006 \u0003מביא,\u0004 ומשום כך, אף על פי שהמביא גט ממדינת הים צריך לומר \"בפני נכתב ובפני נחתם\", המוליך לשם אינו צריך.","\u0003ורבנן בתראי סברי\u0004 \u0005[וחכמים אחרונים סבורים]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 \u0003מוליך אטו\u0004 \u0005[משום]\u0006 \u0003מביא,\u0004 שעשויים אנשים לטעות ולחשוב שכשם שמוליך אינו זקוק להעיד שהגט נכתב ונחתם בפניו, כך המביא לא יזדקק, ולכן תיקנו שגם המוליך למדינת הים צריך להעיד שנכתב הגט ונחתם בפניו.","\u0003ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 כיצד? \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 הטעם של אמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין עדים מצויין לקיימו, ורבנן בתראי\u0004 \u0005[וחכמים אחרונים]\u0006 אינם באים לחלוק על התנא הראשון, אלא \u0003לפרושי טעמיה\u0004 \u0005[לפרש\u0006 את \u0005טעמו]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003הוא דאתו\u0004 \u0005[שבאים],\u0006 שאף הוא סבור שהמוליך צריך להעיד, אלא שאמר דבריו בקיצור.","ומנסים להביא ראיה נוספת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו]: \u0003המביא גט ממדינה למדינה במדינת הים\u0004 — \u0003צריך לומר \"בפני נכתב ובפני נחתם\",\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם הביא גט \u0003באותה מדינה במדינת הים\u0004 — \u0003לא צריך.\u0004 אם כן, \u0003לרבא ניחא\u0004 \u0005[נוח]\u0006 הדבר, שהרי לדעתו הטעם לאמירה זו הוא משום שאין עדים מצויים לקיימו, ובאותה מדינה מצויים הם. ואולם \u0003לרבה\u0004 הסבור שהטעם הוא מפני שאין בקיאים לשמה \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, שהרי אף באותה מדינה שבמדינת הים אינם בקיאים!","ומשיבים: לשיטת רבה \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 אל תדייק\u0005]:\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003באותה מדינה במדינת הים\u0004 — \u0003לא צריך, אלא אימא\u0004 \u0005[אמור\u0006 ודייק\u0005]\u0006 בדרך אחרת: \u0003ממדינה למדינה בארץ ישראל\u0004 — \u0003לא צריך.\u0004","על תירוץ זה מקשים: דבר זה אינו צריך ללומדו בדרך דיוק, \u0003הא בהדיא קתני לה\u0004 \u0005[הרי במפורש\u0006 הוא \u0005שונה אותה]\u0006 במשנה: \u0003המביא גט בארץ ישראל, אינו צריך לומר \"בפני נכתב ובפני נחתם\"!\u0004 ומשיבים: \u0003אי מההיא, הוה אמינא\u0004 \u0005[אם מזו\u0006 בלבד, \u0005הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003דיעבד\u0004 שאם לא עשה כן — לא נפסל הגט, \u0003אבל לכתחילה לא\u0004 ינהג כך, אלא יעיד על הדבר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 דיוק זה שאף לכתחילה אינו צריך.","זו היתה גרסה אחת של דיון זה, \u0003ואיכא דמותיב לה הכי\u0004 \u0005[ויש שמקשה אותה כך]\u0006 באופן אחר, ומדייק מלשון המשנה: המביא גט ממדינה למדינה במדינת הים צריך לומר \"בפני נכתב\" וכו', \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ממדינה למדינה בארץ ישראל\u0004 — \u0003לא צריך\u0004 להביא עדים.","\u0003לרבה ניחא\u0004 \u0005[נוח]\u0006 הדבר, שהרי לדעתו בארץ ישראל אין צורך בעדים כיון שהם בקיאים לשמה. ואילו \u0003לרבא קשיא\u0004 \u0005[קשה]!\u0006 ודוחים: \u0003לא תימא\u0004 \u0005[תאמר]\u0006 ותדייק \u0003ממדינה למדינה בארץ ישראל\u0004 — \u0003לא צריך, אלא אימא\u0004 \u0005[אמור]\u0006 ודייק כך: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003באותה מדינה במדינת הים\u0004 — \u0003לא צריך.\u0004","וממשיכים להקשות: ולשיטה זו \u0003אבל ממדינה למדינה בארץ ישראל, מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003צריך\u0004 להעיד? אם כן, \u0003ליתני\u0004 \u0005[שישנה]\u0006 באופן כללי: \u0003המביא ממדינה למדינה\u0004 — \u0003סתם\u0004 צריך לומר \"בפני נכתב\" וכו', ובכלל זה גם מדינת הים וגם ארץ ישראל!","ומשיבים: \u0003לעולם ממדינה למדינה בארץ ישראל נמי\u0004 \u0005[גם כן]\u0006 \u0003לא צריך,\u0004 וטעמו של דבר: ש\u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003עולי רגלים\u0004 הבאים לבית המקדש, \u0003מישכח שכיחי\u0004 \u0005[מצויים]\u0006 עדים לבוא אפילו ממדינה למדינה.","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003בזמן שבית המקדש קיים,\u0004 שאז היו עולי רגל ועדים מצויים, אבל \u0003בזמן שאין בית המקדש קיים, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003בתי דינין\u0004 מרכזיים \u0003דקביעי\u0004 \u0005[ש\u0006הם \u0005קבועים]\u0006 ונמצאים במקום אחד והכל באים אליהם — \u0003מישכח שכיחי\u0004 \u0005[מצויים]\u0006 עדים לקיימו.","ומביאים ראיה נוספת, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: אפילו מהגמוניא להגמוניא\u0004 צריך המביא גט לומר \"בפני נכתב ובפני נחתם\". \u0003ואמר ר' יצחק: עיר אחת היתה בארץ ישראל ועססיות שמה, והיו בה שני הגמוניות\u0004 שחילקו ביניהן את העיר, \u0003שהיו מקפידין זה על זה\u0004 עד שאי אפשר היה לעבור ממקום למקום באותה עיר, \u0003לפיכך הוצרכו לומר מהגמוניא להגמוניא.\u0004","\u0003לרבא\u0004 שסבור שהטעם הוא משום עדים \u0003ניחא\u0004 \u0005[נוח]\u0006 הדבר, \u0003לרבה קשיא\u0004 \u0005[קשה]\u0006 הדבר, שהרי לשיטת רבה בארץ ישראל שבקיאים בה בענין \"לשמה\" אין צורך באמירת \"בפני נכתב\" וכו'! ומשיבים: \u0003רבה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005],\u0006 גם כן את שיטתו של \u0003רבא,\u0004 כלומר, גם רבה מסכים שאחד הטעמים להלכה זו הוא משום שאין עדים מצויים לקיימו אלא שהוא מוסיף על כך גם טעם נוסף — שאין בקיאים לשמה.","ושואלים: \u0003אלא\u0004 לפי הסבר זה שאנו עתה מסבירים, \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 להלכה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 במקרה \u0003דאתיוה בי תרי\u0004 \u0005[שהביאוהו,\u0006 את הגט \u0005שנים]\u0006 ממדינת הים, שלדעת רבא אינם צריכים לומר \"בפני נכתב\" וכו', שהרי שוב לא ניתן לערער על הגט, ואין צורך בעדים נוספים לקיימו. ואילו לדעת רבה החושש גם משום \"לשמה\" עדיין צריך לומר זאת.","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 הביאו \u0003באותה מדינה במדינת הים,\u0004 שמצויים עדים לקיימו, שלדעת רבה צריך עדים משום \"לשמה\", ולדעת רבא אין צריך.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003המביא גט ממדינת הים, ואינו יכול לומר \"בפני נכתב ובפני נחתם\", אם יש עליו,\u0004 על גט זה, \u0003עדים\u0004 — \u0003יתקיים בחותמיו,\u0004 כלומר, יקיימו אותו על פי אישור חתימת העדים. \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה,\u0004 בהלכה זו: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ואינו יכול לומר\"?\u0004"],["\u0003אילימא\u0004 \u0005[אם לומר]\u0006 שהוא \u0003חרש\u0004 ולכן אינו יכול לדבר, וכי \u0003חרש בר איתויי גיטא\u0004 \u0005[בן הבאת גט]\u0006 \u0003הוא,\u0004 וכי ראוי הוא לכך? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכל כשרים להביא את הגט, חוץ מחרש שוטה וקטן\u0004 שאינם ראויים כלל להיות שליחים כיון שאין הם בני דעת!","\u0003ואמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון ש\u0004השליח \u0003נתנו לה,\u0004 את הגט \u0003כשהוא פקח\u0004 (שומע) \u0003ולא הספיק לומר \"בפני נכתב ובפני נחתם\" עד שנתחרש,\u0004 ששליחותו היתה שליחות ראויה, אלא שכעת אינו יכול לומר דבר. \u0003לרבא ניחא\u0004 \u0005[נוח]\u0006 הדבר, ואולם \u0003לרבה קשיא\u0004 \u0005[קשה]:\u0006 מה מועיל אם יתקיים הגט בחותמיו, והרי סוף סוף יש צורך בעדות על כתיבת הגט לשמה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — לא בעיקר התקנה, אלא בדורות אחרונים \u0003לאחר שלמדו\u0004 אף במדינת הים שיש לכתוב גט לשמה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר כשהכל מוחזקים בקיאים, אם כן אפילו אם השליח \u0003יכול\u0004 להעיד \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יצטרך לומר \"בפני נכתב\", ודיו בקיום חתימת העדים! ומשיבים: בכל זאת צריך השליח להעיד, והטעם: \u0003גזירה שמא יחזור דבר לקלקולו,\u0004 ששוב לא יהא ידוע הצורך בכתיבה לשמה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנו גוזרים גזירה זו, גם אם הביא את הגט מי ש\u0003אינו יכול נמי\u0004 \u0005[גם כן]\u0006 לא יועיל קיום הגט בחותמיו, בגלל גזירה זו! ומשיבים: מקרה כזה של \u0003פקח ונתחרש מילתא דלא שכיחא\u0004 \u0005[דבר שאינו מצוי\u0006 הוא\u0005],\u0006 \u0003ומילתא דלא שכיחא\u0004 \u0005[ודבר שאינו מצוי]\u0006 \u0003לא גזור בה רבנן\u0004 \u0005[גזרו בו חכמים].\u0006","ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אשה\u0004 עצמה המביאה את גיטה, שהוא גם כן דבר \u0003דלא שכיחא\u0004 \u0005[שאינו מצוי],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה עצמה מביאה\u0004 את \u0003גיטה, ובלבד שצריכה לומר \"בפני נכתב ובפני נחתם\",\u0004 ומדוע גזרו חכמים שתאמר, הרי אין זה דבר מצוי שהיא בעצמה תהיה שליח להבאת גיטה?! ומשיבים: קבעו חכמים דבר זה כתקנה כדי \u0003שלא תחלוק בשליחות,\u0004 אלא יצטרכו כל השליחים המביאים גט אשה להעיד.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שכך תיקנו, \u0003בעל נמי\u0004 \u0005[גם כן]\u0006 המביא את גט אשתו יצטרך לומר \"בפני נכתב ובפני נחתם\" כדי שלא לחלוק בשליחות! \u0003אלמה תניא\u0004 \u0005[\u0006ו\u0005מפני מה שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הוא,\u0004 הבעל \u0003עצמו שהביא\u0004 את \u0003גיטו, אין צריך לומר \"בפני נכתב ובפני נחתם\"?\u0004","ומשיבים: \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 ש\u0003צריך\u0004 שליח הגט \u0003לומר \"בפני נכתב ובפני נחתם\" - דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 ה\u0003בעל מערער\u0004 \u0005[ויערער]\u0006 \u0003ופסיל ליה\u0004 \u0005[ויפסול אותו]\u0006 את הגט, ואולם במקרה זה, וכי \u0003השתא מינקט נקיט ליה בידיה\u0004 \u0005[עכשיו\u0006 הוא \u0005מחזיק אותו בידו]\u0006 \u0003וערעורי קא מערער עליה\u0004 \u0005[ומערער עליו]?\u0006 שאם אינו רוצה לתתו יקרענו! ולכן אין טעם לגזור במקרה זה.","ומנסים להביא ראיה נוספת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דבעא מיניה\u0004 \u0005[ששאל אותו]\u0006 \u0003שמואל מרב הונא: שנים שהביאו גט ממדינת הים,\u0004 האם \u0003צריכין שיאמרו \"בפנינו נכתב ובפנינו נחתם\" או אין צריכין? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין צריכין.\u0004 ונתן טעם לדבר: \u0003ומה אילו יאמרו\u0004 ויעידו רק \u0003\"בפנינו גרשה\",\u0004 בלי להביא גט, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מהימני\u0004 \u0005[יהיו נאמנים\u0006 הם בכך\u0005]\u0006 ותיחשב כגרושה? ואם כן, כאשר הם באים ומביאים את הגט הריהם נאמנים שהיו הגירושין כתיקונם.","\u0003ל\u0004שיטת \u0003רבא ניחא\u0004 \u0005[נוח]\u0006 הדבר, כיון שהכל תלוי במציאותם של עדים לקיימו, והרי שני עדים לפנינו, אולם \u0003לרבה קשיא\u0004 \u0005[קשה]\u0006 שהרי יש צורך גם בעדות שנכתב לשמה! ומשיבים: לשיטתו צריכים לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003לאחר שלמדו\u0004 במדינת הים שהגט צריך להיכתב לשמה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר לאחר שלמדו, \u0003חד\u0004 \u0005[אחד]\u0006 שמביא את הגט \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יצטרך לומר \"בפני נכתב\" וכו'! ומשיבים: עד אחד עדיין צריך לומר, והטעם: \u0003גזרה שמא יחזור דבר לקלקולו.\u0004","ומקשים שוב: \u0003אי הכי, בי תרי נמי\u0004 \u0005[אם כך, שניים גם כן]\u0006 יצטרכו לומר אף הם \"בפני נכתב\" וכו', משום הגזירה! ומשיבים: \u0003בי תרי דמייתו גיטא, מילתא דלא שכיחא\u0004 \u0005[שניים שמביאים גט, דבר שאינו מצוי\u0006 הוא\u0005],\u0006 \u0003ומילתא דלא שכיחא\u0004 \u0005[ודבר שאינו מצוי]\u0006 \u0003לא גזור בה רבנן\u0004 \u0005[גזרו בו חכמים].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אשה\u0004 המביאה את גיטה שדבר ש\u0003לא שכיחא\u0004 \u0005[מצוי]\u0006 הוא, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה עצמה מביאה\u0004 את \u0003גיטה, ובלבד שהיא עצמה צריכה לומר \"בפני נכתב ובפני נחתם\"!\u0004 ומשיבים: הטעם בזה הוא כדי \u0003שלא תחלוק בשליחות\u0004 של יחיד.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003בעל נמי\u0004 \u0005[גם כן]\u0006 יצטרך לומר! \u0003אלמה תניא\u0004 \u0005[\u0006ו\u0005מפני מה שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הוא,\u0004 הבעל \u0003עצמו שהביא\u0004 את \u0003גיטו, אינו צריך לומר \"בפני נכתב ובפני נחתם\"?\u0004 ומשיבים: \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 ש\u0003צריך לומר \"בפני נכתב ובפני נחתם\"\u0004 — \u0003דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 ה\u0003בעל מערער ופסיל ליה\u0004 \u0005[יערער ויפסול אותו,\u0006 את הגט\u0005],\u0006 \u0003השתא מינקט נקיט ליה בידיה וערעורי קא מערער עליה\u0004 \u0005[עכשיו\u0006 הוא \u0005מחזיק אותו בידו ומערער עליו]?\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: שליח ה\u0003מביא גט ממדינת הים, ונתנו לה,\u0004 לאשה \u0003ולא אמר לה \"בפני נכתב ובפני נחתם\", אם נתקיים הגט בחותמיו,\u0004 שהעידו אחרים על חתימת העדים — הרי זה גט \u0003כשר, ואם לאו\u0004 \u0005[לא]\u0006 — הריהו \u0003פסול. הוי, לא הוצרכו לומר \"בפני נכתב ובפני נחתם\" להחמיר עליה, אלא להקל עליה\u0004 שלא תהא זקוקה לקיים את הגט.","וברייתא זו \u0003לרבא ניחא\u0004 \u0005[נוחה],\u0006 \u0003לרבה קשיא\u0004 \u0005[קשה]\u0006 היא, שהרי לדעתו אמירת \"בפני נכתב\" וכו' באה להחמיר בדבר משום חשש \"לשמה\"! ומתרץ רבה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003לאחר שלמדו.\u0004","ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003גזירה שמא יחזור הדבר לקלקולו,\u0004 ומפני מה לא גזרו פה? ומשיבים: כאן מדובר \u0003כשניסת\u0004 (כשנישאה) כבר האשה, ולא רצו להחמיר להוציאה מבעלה השני רק משום גזירה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, מה שנאמר שם: \u0003הוי לא הוצרכו לומר \"בפני נכתב ובפני נחתם\" להחמיר עליה אלא להקל עליה,\u0004 לא זה הטעם, אלא \u0003משום\u0004 ש\u0003ניסת\u0004 (נישאה) \u0003הוא,\u0004 שזה הוא הטעם של ההיתר!","ומשיבים: באמת \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 זו היתה כוונתו, וכך יש להבין את הדברים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003להחמיר עלה ולפקה\u0004 \u0005[שנחמיר עליה ונוציא אותה\u0006 מבעלה\u0005]\u0006 — \u0003הוי לא הוצרכו לומר \"בפני נכתב ובפני נחתם\" להחמיר עליה אלא\u0004 \u0003להקל עליה,\u0004 ומשום כך לא עמדו חכמים במקרה זה על קיום גזירתם,"],["שהרי \u0003טעמא מאי\u0004 \u0005[מה הטעם]\u0006 שהצריכו בכלל עדות זו — \u0003דילמא אתי\u0004 \u0005[שמא יבוא]\u0006 ה\u0003בעל מערער ופסיל ליה\u0004 \u0005[\u0006ו\u0005יערער ויפסול אותו],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 כשה \u0003בעל לא קא מערער\u0004 \u0005[אינו מערער]\u0006 ורואה שהיא נישאת, \u0003אנן ניקום ונערער עלה\u0004 \u0005[אנו נעמוד ונערער עליו]?\u0006","ומעירים: רבה ורבא חולקים הם \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' יוחנן ור' יהושע בן לוי, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 טעם לתקנת אמירת \"בפני נכתב ובפני נחתם\": \u0003לפי שאין בקיאין לשמה, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: לפי שאין עדים מצויין לקיימו.\u0004","ומוסיפים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' יהושע בן לוי הוא\u0004 זה ש\u0003אמר\u0004 שהטעם הוא \u0003לפי שאין בקיאין לשמה.\u0004 ומה הראיה לדבר? — ש\u0003ר' שמעון בר אבא אייתי גיטא לקמיה\u0004 \u0005[הביא גט לפני]\u0006 \u0003ר' יהושע בן לוי, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003צריכנא למימר\u0004 \u0005[\u0006האם \u0005צריך אני לומר]\u0006 \u0003\"בפני נכתב ובפני נחתם\", או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אינך צריך],\u0006 שכן, \u0003לא אמרו\u0004 שצריך לומר כן \u0003אלא בדורות הראשונים, שאין בקיאין לשמה, אבל בדורות האחרונים שבקיאין לשמה\u0004 — \u0003לא,\u0004 אם כן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שהוא החכם שסבר שהטעם הוא משום כתיבה לשמה.","ותוהים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור\u0006 כן\u0005]\u0006 שאין שליח יחידי צריך לומר \"בפני נכתב ובפני נחתם\"? \u0003והא\u0004 \u0005[והרי]\u0006 כבר הוכחנו שגם \u0003רבה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 גם את שיטת \u0003רבא\u0004 ובעיה זו של מציאות עדים אינה נפתרת רק על ידי זה שדורות אחרונים למדו כתיבת גט לשמה! \u0003ועוד, הא אמרינן\u0004 \u0005[הרי אנו אומרים]\u0006 לשיטת רבה שצריך להמשיך ולומר \"בפני נכתב\" וכו' \u0003שמא יחזור דבר לקלקולו!\u0004","\u0003אלא,\u0004 כך צריך לומר: \u0003ר' שמעון בר אבא איניש אחרינא הוה בהדיה\u0004 \u0005[איש אחר,\u0006 נוסף, \u0005היה איתו\u0006 כעד\u0005],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003לא חשיב ליה\u0004 \u0005[מנה אותו]\u0006 במעשה זה — \u0003משום כבודו\u0004 של \u0003ר' שמעון\u0004 בר אבא, שאותו אדם היה אדם פשוט ולכן לא הוזכר, אבל כיון שהיו שני עדים, החשש שאין עדים מצויים אינו קיים כאן, ובמקרה כזה שהוא לא מצוי אף אין אנו גוזרים משום החשש שמא יחזור הדבר לקלקולו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003בפני כמה נותנו\u0004 השליח המביא את הגט מחוצה לארץ \u0003לה,\u0004 לאשה? \u0003ר' יוחנן ור' חנינא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: בפני שנים\u0004 נותנו, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: בפני שלשה\u0004 נותנו.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' יוחנן הוא\u0004 ש\u0003אמר בפני שנים.\u0004 ומה הראיה? ש\u0003רבין בר רב חסדא אייתי גיטא לקמיה\u0004 \u0005[הביא גט לפני]\u0006 \u0003ר' יוחנן, ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003זיל הב\u0004 \u0005[לך תן]\u0006 \u0003לה\u0004 את הגט \u0003באפי תרי\u0004 \u0005[בפני שניים]\u0006 \u0003ואימא להו\u0004 \u0005[ואמור להם]\u0006 \u0003\"בפני נכתב ובפני נחתם\".\u0004 ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שזוהי שיטת ר' יוחנן.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם נאמר\u0006 ש\u0005ב\u0006ענין \u0005זה הם חלוקים],\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 \u0003בפני שנים, קסבר\u0004 \u0005[סבור]\u0006 שהטעם הוא: \u0003לפי שאין בקיאין לשמה,\u0004 וכיון שהעיד שנכתב הדבר לשמו — די בכך, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שצריך שיעיד \u0003בפני שלשה, קסבר\u0004 \u0005[סבור]:\u0006 \u0003לפי שאין עדים מצויין לקיימו,\u0004 ולכן צריך להעיד בפני שלושה שהם בית דין כפי שמעידים בכל קיום שטרות?","ודוחים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור\u0006 כן\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מ\u0004כיון ש\u0003ר' יהושע בן לוי אמר,\u0004 כפי שהוכחנו, שהטעם הוא \u0003לפי שאין בקיאין לשמה,\u0004 ממילא מובן כי \u0003ר' יוחנן\u0004 החולק עליו, הוא ש\u0003אמר לפי שאין עדים מצויין לקיימו. והכא היכי קאמר\u0004 \u0005[וכאן איך אומר]\u0006 \u0003ר' יוחנן בפני שנים?\u0004 שאם הטעם לשלושה הוא מפני הצורך לקיים את השטר, היה דווקא ר' יוחנן צריך לומר שיקיימנו בפני שלושה!","\u0003ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003רבה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003רבא.\u0004 ואם כן, גם האומר שאין בקיאים לשמה, מכל מקום צריך עדים לקיימו, ואם צריך בית דין לכך — הלא אין שנים בית דין!","\u0003אלא,\u0004 יש לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 במחלוקת זו, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עדים מצויין לקיימו, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אחרת נחלקו: האם \u0003שליח\u0004 בדבר \u0003נעשה עד\u0004 להעיד על אותו דבר עצמו, \u0003ו\u0004האם \u0003עד נעשה דיין\u0004 באותו דין עצמו, \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 וכך נפרש: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמעיד \u0003בפני שנים, קסבר\u0004 \u0005[סבור]:\u0006 \u0003שליח נעשה עד,\u0004 \u0003ועד נעשה דיין,\u0004 ואם כן, שליח זה שמעיד על אמיתות הגט, הריהו מצטרף לשנים האחרים והם נעשים בית דין ומקיימים אותו. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בפני שלשה, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 אמנם \u0003שליח נעשה עד,\u0004 אבל \u0003אין עד נעשה דיין,\u0004 ומשום כך צריך השליח שלושה כדי להעיד בפניהם.","ומקשים: \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 שדברים שהם \u0003בדרבנן\u0004 \u0005[מדברי סופרים\u0006 בלבד\u0005]\u0006 ש\u0003עד נעשה\u0004 בהם \u0003דיין\u0004 והצורך בקיום שטרות הוא מדברי סופרים, ובזה יכול עד להיעשות דיין!","\u0003אלא,\u0004 יש לחזור מהעמדת המחלוקת בנקודה זו, ולומר כי \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן בזה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה]\u0006 ר' חנינא, המצריך לתת את הגט בפני שלושה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון\u0004 שאף \u0003אשה כשירה להביא את הגט,\u0004 יש לחשוש \u0003זמנין דמייתא ליה איתתא וסמכי עלה\u0004 \u0005[פעמים שמביאה אותו אשה ו\u0006אלו שבפניהם הובא הגט \u0005סומכים עליה],\u0006 שאינם יודעים שמה שמספיק להעיד בפני שניים הוא מפני שהעד מצטרף, ויבואו לטעות שדי בשניים בלבד, וכיון שאין אשה מצטרפת לבית דין נמצא שאין כאן בית דין המקבל את העדות ומקיים את הגט. ומשום כך הצריכו בכל מקרה שלושה.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יוחנן, סבור בענין זה של אשה: \u0003אשה\u0004 — \u0003מידע ידעי ולא סמכי עלה\u0004 \u0005[יודעים\u0006 אנשים שאינה יכולה לדון \u0005ואין סומכים עליה]\u0006 ואז מביאים עוד אדם שלישי, ואין מקום לגזור בדבר.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 שאינו מצריך אלא שניים שיעיד השליח בפניהם: \u0003המביא גט ממדינת הים, ונתנו לה ולא אמר לה \"בפני נכתב ובפני נחתם\"\u0004 והלכה ונישאה לאחר — \u0003יוציא\u0004 הבעל השני את האשה בגט, \u0003והולד\u0004 שנולד מנישואים אלה \u0003ממזר\u0004 הוא, אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים : אין הולד\u0004 מן השני \u0003ממזר. כיצד יעשה\u0004 לתקן את הדברים כראוי? יחזור השליח ו\u0003יטלנו הימנה\u0004 (ממנה), את הגט \u0003ויחזור ויתננו לה בפני שנים, ויאמר \"בפני נכתב ובפני נחתם\".\u0004 ואף שהמחלוקת היתה בענין אחר, מכל מקום מפורש בה שצריך לומר בפני שניים ולא בפני שלושה.","כיון שהבאנו את הברייתא, תוהים: \u0003ור' מאיר\u0004 מה הוא סבור, וכי \u0003משום\u0004 ש\u0003לא אמר\u0004 השליח \u0003\"בפני נכתב ובפני נחתם\" יוציא והולד ממזר?\u0004 הרי מדובר גם במקרה שהעד ראה את כתיבת וחתימת הגט, ורק מפני שלא אמר יחמירו בו עד כדי כך!?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003ר' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין זה. ש\u0003אמר רב המנונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: אומר היה ר' מאיר: כל המשנה\u0004 כל דבר \u0003ממטבע\u0004 (צורה, תבנית) \u0003שטבעו חכמים בגיטין\u0004 — הרי זה \u0003יוציא\u0004 את האשה שנישאה לו על סמך גט כזה, \u0003והולד ממזר.\u0004","מסופר: \u0003בר הדיא בעי לאתויי גיטא\u0004 \u0005[רצה להביא גט]\u0006 ממדינה למדינה, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אחי דהוה\u0004 \u0005[שהיה]\u0006 \u0003ממונה אגיטי\u0004 \u0005[על הגיטין]\u0006 לשאול אותו מה עליו לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003צריך אתה לעמוד על כל אות ואות\u0004 בזמן כתיבת הגט, ולראות שהכל נעשה כראוי. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי ור' אסי, אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אין אתה צריך\u0006 לכך\u0005],\u0006 אלא די שאתה נמצא במקום, ורואה שבכלל נעשה הדבר כראוי.","\u0003וכי תימא אעביד לחומרא\u0004 \u0005[ואם תאמר אעשה\u0006 אני \u0005לחומרה]\u0006 כדעת ר' אחי שמחמיר בזה, \u0003נמצא אתה מוציא לעז על גיטין הראשונים\u0004 שהשליחים שהביאום לא בדקו בהם עד כדי כך.","מסופר: \u0003רבה בר בר חנה אייתי גיטא\u0004 \u0005[הביא גט],\u0006 \u0003פלגא איכתב קמיה ופלגא\u0004 \u0005[חצי נכתב לפניו, וחצי]\u0006 \u0003לא איכתב קמיה\u0004 \u0005[נכתב לפניו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אלעזר\u0004 כדי לברר מה הדין בענין זה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו\u0004 אם \u0003לא כתב בו\u0004 הסופר \u0003אלא שיטה\u0004 (שורה) \u0003אחת לשמה\u0004 בפניו, \u0003שוב אינו צריך\u0004 להסתכל עוד ודיו בכך, שמן הסתם גם גמרו לשמה. \u0003רב אשי אמר:\u0004"],["\u0003אפילו\u0004 שמע \u0003קן קולמוסא וקן מגילתא\u0004 \u0005[קול הקולמוס וקול המגילה]\u0006 שנשמע כשכותב הסופר את הגט לשם אותה אשה — דיו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אשי: המביא גט ממדינת הים, אפילו הוא\u0004 נמצא \u0003בבית\u0004 כשנכתב הגט \u0003וסופר בעלייה,\u0004 או \u0003הוא בעלייה וסופר בבית, אפילו נכנס ויוצא כל היום כולו\u0004 — \u0003כשר\u0004 הגט, ויכול להעיד עליו שנכתב כראוי.","ויש לברר: אם \u0003הוא בבית וסופר בעלייה, הא לא קא חזי ליה\u0004 \u0005[הרי אינו רואה אותו]\u0006 כלל! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר כאן \u0003כגון דשמע קן קולמוסא וקן מגילתא\u0004 \u0005[ש\u0006הוא \u0005שומע קול הקולמוס וקול המגילה].\u0006","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה הברייתא: \u0003אפילו נכנס ויוצא כל היום כולו\u0004 — \u0003כשר.\u0004 ויש לשאול: \u0003מאן\u0004 \u0005[מי הוא]\u0006 זה הנכנס ויוצא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן ב\u0003שליח\u0004 שצריך אחר כך להעיד על הגט, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 שנינו כבר שאם \u0003הוא בבית וסופר בעלייה, דלא חזי ליה\u0004 \u0005[שאינו רואה אותו]\u0006 כלל — \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003כשר\u0004 הוא, אם כן \u0003נכנס ויוצא\u0004 באותו מקום עצמו בו נכתב הגט \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שכשר? \u0003אלא\u0004 תפרש שמדובר כאן ב\u0003סופר\u0004 עצמו שנכנס ויוצא כל היום ואינו כותב את הגט ברציפות, ואולם דבר זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 וכי \u0003משום\u0004 ש\u0003נכנס ויוצא נפסליניה\u0004 \u0005[נפסול אותו]?\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דנפק\u0004 \u0005[שיצא]\u0006 הסופר \u0003לשוקא ואתא\u0004 \u0005[לשוק ובא,\u0006 שב\u0005]\u0006 לביתו לכתוב גט, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 אולי נחשוש שמא באותה יציאה \u0003איניש אחרינא אשכחיה\u0004 \u0005[אדם אחר מצאו]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לכתוב לו גט עבורו, והוא יושב עכשיו וכותב גט לשמה של אשה אחרת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006 התנא\u0005]\u0006 שבכל זאת כשר הגט, ואין חוששים לכך.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה הבאה: \u0003בבל\u0004 מה דינה? \u0003רב אמר:\u0004 דינה \u0003כארץ ישראל ל\u0004ענין \u0003גיטין, ושמואל אמר: כחוצה לארץ.\u0004","ומציעים: \u0003לימא בהא קא מיפלגי\u0004 \u0005[האם לומר\u0006 כי \u0005בזה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 רב\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 שהטעם לתקנת אמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין בקיאין לשמה, והני גמירי\u0004 \u0005[ואלה,\u0006 בני בבל, \u0005למודים\u0006 ובקיאים\u0005],\u0006 \u0003ומר\u0004 \u0005[וחכם זה,\u0006 שמואל\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לפי שאין עדים מצויין לקיימו, והני נמי\u0004 \u0005[ואלה,\u0006 בני בבל, \u0005גם כן]\u0006 \u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 בבבל.","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי יכול \u0005אתה לסבור\u0006 כן\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 סיכמנו כבר כי גם \u0003רבה\u0004 הסבור שחוששים לענין לשמה \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 גם הוא את שיטת \u0003רבא\u0004 שצריכים עדים לקיימו. ולכן, אף שבקיאים לשמה בבבל, כיון שאין עדים מצויים שם, צריך להיות דינה כחוצה לארץ!","\u0003אלא,\u0004 יש לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 עדים \u0003לקיימו,\u0004 ובזה הם חלוקים, \u0003רב סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דאיכא מתיבתא\u0004 \u0005[שיש ישיבות]\u0006 מרכזיות שאנשים באים אליהן, לכך \u0003מישכח שכיחי\u0004 \u0005[מצויים]\u0006 עדים לקיים את הגט, \u0003ושמואל סבר\u0004 \u0005[סבור]:\u0006 \u0003מתיבתא בגירסייהו טרידי\u0004 \u0005[\u0006לומדי \u0005הישיבות בלימודם\u0006 הם \u0005טרודים]\u0006 ואין הבאים אליהן עשויים לשמש כעדי קיום.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 ש\u0003אמר ר' אבא אמר רב הונא: עשינו עצמינו בבבל כארץ ישראל לגיטין, מכי אתא\u0004 \u0005[מ\u0006הזמן \u0005אשר\u0006 בו \u0005בא]\u0006 \u0003רב לבבל.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' ירמיה\u0004 ממה ששנינו במשנתנו, \u0003ר' יהודה אומר: מרקם ל\u0004צד \u0003מזרח\u0004 הרי זה מדינת הים, \u0003ורקם\u0004 עצמה — \u0003כמזרח, מאשקלון לדרום, ואשקלון\u0004 עצמה — \u0003כדרום, מעכו לצפון, ועכו\u0004 עצמה — \u0003כצפון. והא\u0004 \u0005[והרי]\u0006 \u0003בבל לצפונה\u0004 של \u0003ארץ ישראל קיימא\u0004 \u0005[\u0006היא \u0005עומדת],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בנבואה על החורבן שיבוא על ידי בבל: \u0003\"ויאמר ה' אלי מצפון תפתח הרעה\"\u0004 (ירמיה א, יד),","\u0003ותנן\u0004 \u0005[ו\u0006אף \u0005שנינו],\u0006 \u0003ר' מאיר אומר: עכו\u0004 — \u0003כארץ ישראל לגיטין, ו\u0004מכל מקום, \u0003אפילו ר' מאיר לא קאמר\u0004 \u0005[אומר]\u0006 \u0003אלא בעכו דמקרבא\u0004 \u0005[ש\u0006היא \u0005קרובה]\u0006 לארץ ישראל, \u0003אבל בבל דמרחקא\u0004 \u0005[ש\u0006היא \u0005רחוקה]\u0006 \u0003לא!\u0004 ומוסיפים: \u0003הוא,\u0004 ר' ירמיה, היה \u0003מותיב לה\u0004 \u0005[מקשה אותה,\u0006 את הקושיה הזו\u0005],\u0006 \u0003והוא\u0004 עצמו היה \u0003מפרק לה\u0004 \u0005[מתרץ אותה],\u0006 שהגבלה זו של תחומי ארץ ישראל נאמרה \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מבבל.\u0004","ומבררים: \u0003עד היכן היא בבל?\u0004 מהו תחומה של בבל לענין זה? \u0003אמר רב פפא: כמחלוקת\u0004 שיש במסכת קדושין ביחס לגבולותיה של בבל \u0003ל\u0004ענין \u0003יוחסין,\u0004 מי נחשבים כיהודי בבל העיקריים שהם מיוחסים, \u0003כך מחלוקת ל\u0004ענין \u0003גיטין. ורב יוסף אמר:\u0004 ה\u0003מחלוקת\u0004 שנאמרה שם היא רק \u0003ל\u0004ענין \u0003יוחסין, אבל ל\u0004ענין \u0003גיטין\u0004 — \u0003דברי הכל\u0004 תחומה של בבל הוא \u0003עד ארבא תניינא דגישרא\u0004 \u0005[הקשת השניה של הגשר]\u0006 שעל נהר הפרת.","מסופר: \u0003רב חסדא\u0004 היה \u0003מצריך\u0004 את מביאי הגיטין לומר \"בפני נכתב ובפני נחתם\" אפילו כשהיו מביאים גט \u0003מאקטיספון לבי ארדשיר,\u0004 אבל גיטין שהיו מביאים \u0003מבי ארדשיר לאקטיספון לא\u0004 היה \u0003מצריך.\u0004 ושואלים: \u0003לימא קסבר\u0004 \u0005[האם לומר\u0006 שהוא \u0005סבור]\u0006 שהטעם לתקנת \"בפני נכתב ובפני נחתם\" \u0003לפי שאין בקיאין לשמה, והני\u0004 \u0005[ואלה]\u0006 בארדשיר \u0003גמירי\u0004 \u0005[למודים\u0006 הם בדבר\u0005]?\u0006","ותוהים: \u0003ותסברא\u0004 \u0005[וכי\u0006 יכול \u0005אתה לסבור\u0006 כן\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 גם \u0003רבה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003רבא\u0004 שיש צורך בקיום! \u0003אלא\u0004 כך צריך לומר: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו עדים מצויים \u0003לקיימו, והני\u0004 \u0005[ואלה]\u0006 בני ארדשיר \u0003כיון דאזלי לשוקא להתם\u0004 \u0005[ש\u0006הם \u0005הולכים לשוק לשם,\u0006 לאקטיספון\u0005],\u0006 \u0003הנך ידעי בחתימות ידא דהני\u0004 \u0005[אלה,\u0006 בני אקטיספון \u0005יודעים בחתימות ידם של אלה,\u0006 בני ארדשיר\u0005],\u0006 שהיו באים לשם לצורך עסקיהם ולכן הכירו את חתימותיהם,","\u0003והני בדהנך לא ידעי\u0004 \u0005[ואלה,\u0006 בני ארדשיר, \u0005ב\u0006חתימותיהם \u0005של אלה,\u0006 בני אקטיספון, \u0005אינם יודעים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003בשוקייהו טרידי\u0004 \u0005[בשוקם\u0006 הם \u0005טרודים]\u0006 לקנות ולמכור את סחורתם, ואינם מכירים בשטרותיהם של בני אקטיספון.","מסופר, כי \u0003רבה בר אבוה\u0004 היה \u0003מצריך\u0004 להעיד אפילו כשמביאים גט \u0003מערסא לערסא\u0004 \u0005[מצד\u0006 אחד של רשות הרבים \u0005לצידה\u0006 השני\u0005].\u0006 \u0003רב ששת\u0004 היה \u0003מצריך משכונה\u0004 (קבוצת בתים) אחת \u0003לשכונה\u0004 אחרת אפילו בצד אחד של רשות הרבים, \u0003ורבא\u0004 היה \u0003מצריך\u0004 לומר \"בפני נכתב ובפני נחתם\" אפילו \u0003באותה שכונה.\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא\u0004 ש\u0003אמר\u0004 שהטעם שצריך להעיד הוא \u0003לפי שאין עדים מצויין לקיימו,\u0004 ואיך אפשר לומר שבאותה שכונה אין עדים מצויים לקיימו? ומשיבים: דבר זה קבע רבא רק במקומו, בעירו מחוזא, כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003בני מחוזא, דניידי\u0004 \u0005[ש\u0006הם \u0005נודדים]\u0006 תמיד ואינם קבועים במקומם, ולכן ייתכן שהעדים שהיו שם בזמנם כבר הלכו להם למקום אחר.","\u0003רב חנין מישתעי\u0004 \u0005[היה מספר]:\u0006 \u0003רב כהנא אייתי גיטא\u0004 \u0005[הביא גט],\u0006 \u0003ולא ידענא\u0004 \u0005[ואין אני יודע]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הביא אותו \u0003מסורא לנהרדעא, אי\u0004 \u0005[אם]\u0006 \u0003מנהרדעא לסורא. אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 בשאלה: \u0003צריכנא למימר\u0004 \u0005[\u0006האם \u0005צריך אני לומר]\u0006 \u0003\"בפני נכתב ובפני נחתם\", או לא צריכנא\u0004 \u0005[איני צריך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אין אתה צריך],\u0006"],["\u0003ואי עבדת\u0004 \u0005[ו\u0006אולם \u0005אם אתה עושה\u0006 כן\u0005]\u0006 — \u0003אהנית\u0004 \u0005[\u0006\u0005אתה מועיל].\u0006 ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 פירושם של מילים אלו \u0003\"אי עבדת, אהנית\"\u0004 \u0005[אם אתה עושה, אתה מועיל]?\u0006 — \u0003דאי אתי\u0004 \u0005[שאם יבוא]\u0006 \u0003בעל\u0004 ו\u0003מערער, לא משגחינן ביה\u0004 \u0005[אין אנו משגיחים בו]\u0006 ובדבריו.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באדם אחד שהביא גט לפני ר' ישמעאל, אמר לו\u0004 בשאלה: האם \u0003צריך אני לומר \"בפני נכתב ובפני נחתם\", או איני צריך? אמר לו: בני, מהיכן אתה? אמר לו: רבי, מכפר סיסאי אני. אמר לו: צריך אתה לומר \"בפני נכתב ובפני נחתם\",\u0004 כדי \u0003שלא תיזקק\u0004 האשה \u0003לעדים\u0004 אם יערער הבעל.","\u0003לאחר שיצא\u0004 אותו אדם, \u0003נכנס לפניו ר' אלעאי, אמר לו: רבי,\u0004 מדוע אמרת לו כן? \u0003והלא כפר סיסאי מובלעת בתחום ארץ ישראל, וקרובה לציפורי,\u0004 שהיתה מעיקר ארץ ישראל עוד \u0003יותר מעכו!\u0004 ומעירים עוד: \u0003ותנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 ש\u0003ר' מאיר אומר: עכו\u0004 — \u0003כארץ ישראל לגיטין, ואפילו רבנן לא פליגי עליה\u0004 \u0005[חכמים אינם חלוקים עליו]\u0006 על \u0003ר' מאיר\u0004 — \u0003אלא בעכו דמרחקא\u0004 \u0005[ש\u0006היא \u0005רחוקה],\u0006 \u0003אבל\u0004 בדבר הצורך לומר \"בפני נכתב ובפני נכתב\" בגט \u0003הבא מ\u0004\u0003כפר סיסאי דמקרבא\u0004 \u0005[ש\u0006היא \u0005קרובה]\u0006 לארץ ישראל — \u0003לא\u0004 נחלקו עליו ואף לדעתם אין צריך לומר!","\u0003אמר לו\u0004 ר' ישמעאל: \u0003שתוק, בני, שתוק, הואיל ויצא הדבר בהיתר\u0004 — \u0003יצא.\u0004 ומכאן ראיה שיש תועלת לאמירת \"בפני נכתב ובפני נחתם\" כדי שייעשה הדבר בהיתר גמור, ולא יהיה מקום לערער יותר.","ושואלים: לשם מה היה צריך ר' ישמעאל להסביר לר' אלעאי? \u0003הא איהו נמי\u0004 \u0005[הרי הוא,\u0006 ר' ישמעאל, \u0005גם כן]\u0006 מתחילה את טעמו של דבר: \u0003\"שלא תיזקק לעדים\" קאמר ליה\u0004 \u0005[אמר לו]!\u0006 ומשיבים: \u0003לא סיימוה\u0004 \u0005[גמרו],\u0006 לא מסרו הנוכחים את סוף דברי ר' ישמעאל \u0003קמיה\u0004 \u0005[לפני]\u0006 ר' אלעאי, ולכן לא ידע מה טעם אמר ר' ישמעאל כך, ולכן תמה עליו.","מסופר: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אביתר\u0004 מארץ ישראל מכתב \u0003לרב חסדא,\u0004 ובו כתב לו כך: \u0003גיטין הבאים משם,\u0004 מבבל, \u0003לכאן,\u0004 לארץ ישראל — \u0003אין צריך לומר \"בפני נכתב ובפני נחתם\".\u0004 ושואלים: \u0003לימא קסבר\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005סבור\u0006 הוא\u0005]\u0006 שהטעם שצריך אמירת \"בפני נכתב\" וכו' הוא \u0003לפי שאין בקיאין לשמה, והני גמירי\u0004 \u0005[ואלה,\u0006 בני בבל, \u0005למודים\u0006 ובקיאים בדבר\u0005]\u0006 ולכן אינם צריכים לומר?","ומקשים: \u0003ותסברא\u0004 \u0005[ו\u0006כי יכול \u0005אתה לסבור כן]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003רבא\u0004 שיש צורך באמירה זו משום קיום הגט?! \u0003אלא,\u0004 יש לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 אמירת \"בפני נכתב\" וכו' משום הטעם שאין עדים מצויים \u0003לקיימו, ו\u0004אולם יש טעם בענין זה; \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003רבים דסלקי ונחתי\u0004 \u0005[שעולים\u0006 לארץ ישראל \u0005ויורדים\u0006 ממנה לבבל] — \u0003מישכח שכיחי\u0004 \u0005[מצויים\u0006 עדים\u0005]\u0006 ואין לחשוש עוד.","\u0003אמר רב יוסף: מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 ש\u0003ר' אביתר בר סמכא\u0004 (ראוי לסמוך עליו) \u0003הוא? ועוד\u0004 יש טעם לפקפק בדבריו: \u0003הא איהו\u0004 \u0005[הרי הוא\u0006 עצמו\u0005]\u0006 ש\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003לרב יהודה\u0004 גם כן במכתב: \u0003בני אדם העולין משם,\u0004 מבבל, \u0003לכאן,\u0004 לארץ ישראל — \u0003הן קיימו בעצמן\u0004 את הפסוק \u0003\"ויתנו (את) הילד בזונה והילדה מכרו ביין וישתו\"\u0004 (יואל ד, ג), כלומר, שאנשים אלה מפקירים את בני משפחתם. \u0003וכתב ליה\u0004 \u0005[לו]\u0006 את המילים הללו \u0003בלא שירטוט,\u0004","\u0003ואמר ר' יצחק\u0004 לגבי כתיבה של פסוק מן התורה: \u0003שתים\u0004 (שתי מילים) \u0003כותבין\u0004 בלא שירטוט, \u0003שלש\u0004 מילים \u0003אין כותבין\u0004 בלא שירטוט, אלא צריך לשרטט שורות לפני הכתיבה כפי שמשרטטים בספר תורה, \u0003במתניתא תנא\u0004 \u0005[\u0006ו\u0005בברייתא שנה]:\u0006 \u0003שלש כותבין, ארבע אין כותבין,\u0004 ואילו ר' אביתר כתב יותר מכך בלי שירטוט, ואם כן, משמע שאינו אדם שאפשר לסמוך עליו להלכה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל\u0004 מי ש\u0003לא ידע\u0004 \u0005[יודע]\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003ר' יצחק, לאו גברא רבה\u0004 \u0005[לא אדם גדול]\u0006 \u0003הוא?\u0004 ומה ההוכחה מכאן? \u0003בשלמא מילתא דתליא בסברא\u0004 \u0005[נניח דבר שתלוי בסברה]\u0006 שמתברר שאינו יודע — \u0003לחיי\u0004 \u0005[בסדר],\u0006 אפשר לומר שאם אינו יודע דבר כזה אינו אדם גדול הראוי לסמוך עליו, ואולם \u0003הא\u0004 \u0005[זו]\u0006 — \u0003גמרא\u0004 \u0005[מסורת]\u0006 \u0003היא, וגמרא\u0004 \u0005[ומסורת\u0006 זו\u0005]\u0006 \u0003לא שמיע ליה\u0004 \u0005[שמע אותה].\u0006","\u0003ועוד\u0004 ראיה שראוי לסמוך עליו, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' אביתר הוא\u0004 זה \u0003דאסכים מריה\u0004 \u0005[שהסכים אדוניו],\u0006 הקדוש ברוך הוא, \u0003על ידיה\u0004 \u0005[ידו].\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במעשה פילגש בגבעה: \u0003\"ותזנה עליו פילגשו\"\u0004 (שופטים יט, ב), ודנו חכמים מה היה אותו מעשה שבגללו כעס עליה עד שברחה ממנו; \u0003ר' אביתר אמר: זבוב מצא לה\u0004 בתבשיל שבישלה עבורו. \u0003ר' יונתן אמר: נימא\u0004 (שערה) \u0003מצא לה.\u0004","\u0003ואשכחיה\u0004 \u0005[ומצא אותו]\u0006 \u0003ר' אביתר לאליהו\u0004 הנביא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי קא עביד\u0004 \u0005[מה עושה]\u0006 \u0003הקדוש ברוך הוא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עסיק\u0004 \u0005[עוסק]\u0006 כעת \u0003ב\u0004ענין \u0003פילגש בגבעה.\u0004 ושאלו ר' אביתר: \u0003ומאי קאמר\u0004 \u0005[ומה\u0006 הוא \u0005אומר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו, כך אומר הקדוש ברוך הוא: \u0003אביתר בני כך הוא אומר, יונתן בני כך הוא אומר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אביתר: \u0003חס ושלום, ומי איכא ספיקא קמי שמיא\u0004 \u0005[וכי יש ספק לפני השמים]?\u0006 האם הקדוש ברוך הוא אינו יודע מה אירע שמזכיר הוא את שתי הדעות החולקות? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003אלו ואלו דברי אלהים חיים הן,\u0004 ושני הדברים אכן אירעו. וכך היה: \u0003זבוב מצא\u0004 בקערה \u0003ולא הקפיד, נימא מצא והקפיד.\u0004","\u0003אמר רב יהודה\u0004 בהסבר הדבר, כך היה מעשה: \u0003זבוב\u0004 מצא \u0003בקערה\u0004 שבישלה לו, \u0003ונימא באותו מקום\u0004 (במקום ערווה). כשמצא \u0003זבוב\u0004 — ענין של \u0003מאיסותא\u0004 \u0005[מיאוס]\u0006 הוא ומשום כך לא הקפיד עליה, \u0003ונימא\u0004 — \u0003סכנתא\u0004 \u0005[סכנה]\u0006 יש בה שמא ייפצע בה ומשום כך הקפיד עליה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 היו \u0003בקערה,\u0004 אלא \u0003זבוב\u0004 — \u0003אונסא\u0004 \u0005[אונס\u0006 הוא\u0005],\u0006 שהזבוב מתעופף ונופל לתוך הקערה, \u0003ונימא\u0004 שנמצאת בקערה — \u0003פשיעותא\u0004 \u0005[פשיעה\u0006 רשלנות היא\u0005].\u0006","ובאותו ענין \u0003אמר רב חסדא: לעולם אל יטיל אדם אימה יתירה בתוך ביתו\u0004 (בני משפחתו), \u0003שהרי פילגש בגבעה הטיל עליה בעלה אימה יתירה, ו\u0004בסופו של דבר \u0003הפילה,\u0004 כלומר, גרמה שנפלו על ידה \u0003כמה רבבות מישראל\u0004 במלחמה שבעקבות אותו מעשה (ראה שופטים כ).","\u0003אמר רב יהודה אמר רב: כל המטיל אימה יתירה בתוך ביתו, סוף הוא בא לידי שלש עבירות: גילוי עריות,\u0004 שמפני שאשתו מפחדת ממנו פעמים שאינה טובלת לנידתה והיא אומרת לו שטבלה, וכן \u0003שפיכות דמים,\u0004 שבורחת מפניו ועשויה להיהרג, \u0003וחילול שבת,\u0004 שמבשלת עבורו בשבת מפני שמפחדת שמא יקפיד עליה כשלא בישלה.","\u0003אמר רבה בר בר חנה: הא דאמרי רבנן\u0004 \u0005[זה שאמרו חכמים]:\u0006 \u0003שלשה דברים צריך אדם לומר בתוך ביתו ערב שבת עם חשיכה: עשרתם? ערבתם? הדליקו\u0004 עכשיו \u0003את הנר! צריך\u0004"],["\u0003למימרינהו בניחותא\u0004 \u0005[לומר אותם בנחת]\u0006 ולא בכעס, \u0003כי היכי דליקבלו מיניה\u0004 \u0005[כדי שיקבלו ממנו]\u0006 את דבריו. \u0003אמר רב אשי: אנא\u0004 \u0005[אני]\u0006 \u0003לא שמיעא לי הא\u0004 \u0005[שמעתי\u0006 את הדבר \u0005הזה]\u0006 של \u0003רבה בר בר חנה, ו\u0004אולם \u0003קיימתיה מסברא\u0004 \u0005[מסברה]\u0006 שכך צריך לעשות.","\u0003אמר ר' אבהו: לעולם אל יטיל אדם אימה יתירה בתוך ביתו, שהרי אדם גדול\u0004 אחד \u0003הטיל אימה יתירה בתוך ביתו והאכילוהו דבר גדול,\u0004 דבר שהיה בו איסור מרובה.","ושואלים: \u0003ומנו\u0004 \u0005[ומי היה\u0006 זה\u0005]?\u0006 ומשיבים: \u0003ר' חנינא בן גמליאל.\u0004 ותוהים: \u0003האכילוהו סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בהמתן של צדיקים אין הקדוש ברוך הוא מביא תקלה על ידם, צדיקים עצמן לא כל שכן?\u0004 ואיך יכול אתה לומר שהגיע עד כדי אכילת דבר אסור!","\u0003אלא\u0004 הכוונה היא ש\u0003בקשו להאכילו דבר גדול, ומאי ניהו\u0004 \u0005[ומה היה זה]?\u0006 \u0003אבר מן החי.\u0004 שיום אחד חסר חלק מבהמה שהביאו לו, ובני ביתו חששו כל כך מפני אימתו הרבה עליהם עד שחתכו איבר מבהמה חיה כדי להשלים, והיה עלול לאכול ממנה.","אגב שדיברנו בדברים שנכתבו מארץ ישראל לבבל ובענין שירטוט, מספרים עוד: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003מר עוקבא\u0004 ראש הגולה בבבל \u0003לר' אלעזר\u0004 שהיה בארץ ישראל אגרת ובה נכתב: \u0003בני אדם העומדים עלי,\u0004 שמציקים לי, \u0003ובידי למסרם למלכות, מהו?\u0004 האם לעשות זאת, או לא?","\u0003שרטט\u0004 ר' אלעזר \u0003וכתב ליה\u0004 \u0005[לו]\u0006 פסוק זה: \u0003\"אמרתי אשמרה דרכי מחטוא בלשוני אשמרה לפי מחסום בעד רשע לנגדי\"\u0004 (תהלים לט, ב), ופירש לו: \u0003אף על פי שרשע לנגדי\u0004 — \u0003אשמרה לפי מחסום.\u0004","\u0003שלח ליה\u0004 \u0005[לו]\u0006 מר עוקבא עוד: \u0003קא מצערי לי טובא, ולא מצינא דאיקום בהו\u0004 \u0005[\u0006הם \u0005מצערים אותי הרבה, ואיני יכול לעמוד בהם]!\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 ר' אלעזר בחזרה כתוב זה בתשובה: \u0003\"דום לה' והתחולל לו\u0004 אל תתחר במצליח דרכו באיש עושה מזימות\u0003\"\u0004 (תהלים לז, ז), ופירושו של כתוב: \u0003דום לה'\u0004 ואל תעשה דבר, \u0003והוא יפילם לך חללים חללים, השכם והערב עליהן לבית המדרש והן כלין מאיליהן.\u0004 ומספרים: \u0003הדבר יצא מפי ר' אלעזר, ונתנוהו לגניבא\u0004 שהיה האיש שחלק על מר עוקבא וציערו, \u0003בקולר,\u0004 כאחד מאלה שנידונים למלכות.","ועוד \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003למר עוקבא\u0004 שאלה זו: \u0003זמרא מנא לן דאסיר\u0004 \u0005[זמר, מניין לנו שאסור]\u0006 בזמן הזה שלאחר החורבן? \u0003שרטט וכתב להו\u0004 \u0005[להם]\u0006 פסוק זה: \u0003\"אל תשמח ישראל אל גיל בעמים\"\u0004 (הושע ט, א).","ושואלים: \u0003ולישלח להו מהכא\u0004 \u0005[ושישלח להם מכאן],\u0006 מפסוק מפורש זה: \u0003\"בשיר לא ישתו יין ימר שכר לשתיו\"\u0004 (ישעיה כד, ט)! ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004הפסוק \u0003ההוא, הוה אמינא\u0004 \u0005[\u0006\u0005הייתי אומר\u0006 כך\u0005]:\u0006 \u0003הני מילי זמרא דמנא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא, ב\u0005זמר שבכלי\u0006 נגינה\u0005],\u0006 כאמור בכתוב \"שבת משוש תופים... שבת משוש כנור\" (ישעיה כד, ח), \u0003אבל דפומא שרי\u0004 \u0005[\u0006זמר \u0005שבפה מותר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכל סוג של שיר אסור.","מתוך שהוזכר המעשה במר עוקבא שהורוהו שלא לנקום במציקים לו, מביאים מעשה אחר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר נתן לרב אשי: מאי דכתיב\u0004 \u0005[מהו\u0006 פירוש מה \u0005שנאמר]\u0006 \"ו\u0003קינה ודימונה ועדעדה\"\u0004 (יהושע טו, כב)? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתוותא\u0004 \u0005[ערים]\u0006 של \u0003ארץ ישראל קחשיב\u0004 \u0005[הוא מונה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003אטו אנא לא ידענא דמתוותא\u0004 \u0005[וכי אני איני יודע שערים]\u0006 שב\u0003ארץ ישראל קא חשיב\u0004 \u0005[הוא מונה]?\u0006 ודאי שזה פשוטו של מקרא! \u0003אלא רב גביהא מארגיזא אמר בה,\u0004 בפסוק ההוא, \u0003טעמא\u0004 \u0005[טעם,\u0006 רמז\u0005]\u0006 לענין אחר, וכך פירש אותו: \u0003כל שיש לו קנאה\u0004 (\"קינה\") \u0003על חבירו, ו\u0004בכל זאת הוא \u0003דומם\u0004 (\"ודימונה\") — זוכה ש\u0003שוכן עדי עד\u0004 (\"עדעדה\") \u0003עושה לו דין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אלא מעתה,\u0004 הפסוק שנאמר בו \u0003\"\u0004ו\u0003צקלג ומדמנה וסנסנה\"\u0004 (יהושע טו, לא), \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן]\u0006 ואף בו אתה דורש?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הוה\u0004 \u0005[אם היה]\u0006 \u0003רב גביהא מבי ארגיזא הכא\u0004 \u0005[כאן],\u0006 \u0003הוה אמר בה טעמא\u0004 \u0005[היה אומר בזה טעם\u0006 רמז\u0005].\u0006 ומספרים: \u0003רב אחא מבי חוזאה אמר בה הכי\u0004 \u0005[כך]:\u0006 \u0003כל מי שיש לו צעקת לגימא\u0004 (\"צקלג\") \u0003על חבירו,\u0004 כלומר, טענה על חבירו שמנע ממנו אוכל, \u0003ודומם\u0004 (\"ומדמנה\") — \u0003שוכן בסנה\u0004 (\"סנסנה\") \u0003עושה לו דין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש גלותא\u0004 \u0005[ראש הגולה]\u0006 \u0003לרב הונא: כלילא\u0004 \u0005[עטרה]\u0006 ששמים בראש החתן \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 ש\u0003אסור\u0004 לעשות כן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אסור הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בפולמוס\u0004 (מלחמה), כלומר, לאחר המלחמה \u0003של אספסיינוס גזרו\u0004 איסור \u0003על עטרות חתנים ועל האירוס\u0004 (מין כלי נגינה).","\u0003אדהכי קם\u0004 \u0005[בינתיים עמד]\u0006 \u0003רב הונא לאפנויי\u0004 \u0005[להיפנות\u0006 לצרכיו\u0005],\u0006 ומשיצא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא\u0004 לראש הגולה, שעד כה לא דיבר מפני כבודו של רב הונא שהיה כרבו, \u0003קרא כתיב\u0004 \u0005[כתוב נאמר]\u0006 בענין זה: \u0003\"כה אמר ה' אלהים הסיר המצנפת והרים העטרה זאת לא זאת השפלה הגבה והגבה השפיל\"\u0004 (יחזקאל כא, לא), ויש לשאול:","\u0003וכי מה ענין מצנפת אצל עטרה?\u0004 הרי אינן בראשו של אותו אדם! \u0003אלא לומר לך: בזמן שמצנפת\u0004 מצוייה \u0003בראש כהן גדול\u0004 כשבית המקדש קיים — \u0003עטרה\u0004 נמצאת \u0003בראש כל אדם,\u0004 כיון ש\u0003נסתלקה מצנפת מראש כהן גדול\u0004 — \u0003נסתלקה עטרה מראש כל אדם.\u0004","\u0003אדהכי אתא\u0004 \u0005[בינתיים חזר]\u0006 \u0003רב הונא, אשכחינהו דהוי יתבי\u0004 \u0005[מצא אותם שהיו יושבים\u0006 ומדברים בכך\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב חסדא בלשון שבועה: \u0003האלהים!\u0004 האיסור הזה אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003אלא חסדא שמך וחסדאין מילך\u0004 \u0005[וחסודים דבריך]\u0006 שמצאת רמז יפה לדבר.","מסופר: \u0003רבינא אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003מר בר רב אשי דהוה גדיל כלילא לברתיה\u0004 \u0005[שהיה קולע עטרה לבתו]\u0006 לנישואיה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר\u0004 \u0005[סבור אדוני]\u0006 כפי שדרשו את הפסוק: \u0003\"הסיר המצנפת והרים העטרה\"? אמר ליה\u0004 \u0005[לו]:\u0006 איסור זה נאמר \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כהן גדול\u0004 ולכן \u0003בגברי\u0004 \u0005[בגברים]\u0006 גזרו שלא ילבשו עטרות, \u0003אבל בנשי\u0004 \u0005[בנשים]\u0006 — \u0003לא\u0004 גזרו.","כיון שהזכרנו פסוק זה, שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"זאת לא זאת\"? דרש ר' עוירא, זימנין\u0004 \u0005[פעמים]\u0006 \u0003אמר לה\u0004 \u0005[אותה]\u0006 את השמועה הזו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמי, וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר לה משמיה\u0004 \u0005[אותה משמו]\u0006 של \u0003רב אסי,\u0004 וכך פירש: \u0003בשעה שאמר הקדוש ברוך הוא לישראל\u0004 בעת החורבן: \u0003\"הסיר המצנפת והרים העטרה\", אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 וכי \u0003זאת\u0004 ראוי לעשות \u0003להן לישראל, שהקדימו לפניך בסיני \"נעשה\" ל\"נשמע\",\u0004 וכך עונשם?","\u0003אמר להן:\u0004 וכי \u0003לא זאת\u0004 ראוי לעשות \u0003להן לישראל, שהשפילו את הגבוה והגביהו את השפל,\u0004 שאינם עובדים את ה' ועובדים עבודה זרה \u0003והעמידו צלם בהיכל?\u0004 וזה הפירוש של המילים \"זאת לא זאת\".","אגב שהוזכרה דרשה במסורת של חכמים אלה, מביאים עוד כיוצא בה: \u0003דרש רב עוירא, זימנין\u0004 \u0005[פעמים]\u0006 \u0003אמר לה\u0004 \u0005[\u0006\u0005אותה\u0006 שמועה\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמי, וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר לה משמיה\u0004 \u0005[אותה משמו]\u0006 של \u0003רב אסי; מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כה אמר ה' אם שלמים וכן רבים וכן נגוזו ועבר\u0004 ועניתיך לא אענך עוד\u0003\"\u0004 (נחום א, יב)? — כך פירושו: \u0003אם רואה אדם שמזונותיו מצומצמין\u0004 — \u0003יעשה מהן צדקה, וכל שכן כשהן מרובין.\u0004 כלומר, אם שלמו (נגמרו) מזונותיו — יעשה צדקה, וכל שכן כשהם רבים.","ושואלים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"וכן נגוזו ועבר\"? תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל הגוזז\u0004 (\"נגוזו\") \u0003מנכסיו ועושה מהן צדקה\u0004 — \u0003ניצל\u0004 (\"עבר\") \u0003מדינה של גיהנם.\u0004 כעין משל לדבר: \u0003משל לשתי רחילות\u0004 (כבשות) \u0003שהיו עוברות במים, אחת\u0004 מהן \u0003גזוזה ואחת\u0004 מהן \u0003אינה גזוזה, גזוזה עברה, ושאינה גזוזה לא עברה,\u0004 משום שהמים נספגו בצמרה וטבעה במים. וכן הוא לענין זה, שמי שגוזז מנכסיו ועושה צדקה אינו נופל בגהינום."],["ודרשו את המשך הפסוק, \u0003\"ועיניתך\"\u0004 — \u0003אמר מר זוטרא:\u0004 לומר ש\u0003אפילו עני המתפרנס מן הצדקה\u0004 אף הוא \u0003יעשה צדקה\u0004 הרמוזה קודם לכן בפסוק. \u0003\"לא אענך עוד\"\u0004 — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 לומר שאם הוא מחלק צדקה לאחרים \u0003שוב אין מראין לו סימני עניות.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: מרקם למזרח וכו',\u0004 מעכו לצפון ועכו כצפון. ומדייקים: \u0003למימרא\u0004 \u0005[יש לומר,\u0006 ללמוד\u0005]\u0006 ולהניח מכאן ש\u0003עכו לצפונה\u0004 של \u0003ארץ ישראל קיימא\u0004 \u0005[\u0006היא \u0005עומדת].\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקום אחר, על פיו מתברר שאין עכו בקצה הצפוני של הארץ, ששנינו: \u0003היה מהלך מעכו לכזיב, מימינו למזרח הדרך\u0004 — האדמה \u0003טמאה משום ארץ העמים, ופטורה מן המעשר ומן השביעית,\u0004 משום שחזקתה היא חוצה לארץ, \u0003עד שיודע לך\u0004 מקום \u0003ש\u0004בו \u0003היא חייבת,\u0004 ואילו","\u0003משמאלו למערב הדרך\u0004 — הריהי \u0003טהורה משום\u0004 דין \u0003ארץ העמים, וחייבת במעשר ובשביעית, עד שיודע לך\u0004 מקום \u0003ש\u0004בו \u0003היא פטורה. עד היכן?\u0004 — \u0003עד כזיב. ר' ישמעאל בר' יוסי אומר משום\u0004 (בשם) \u0003אביו: עד\u0004 המקום הנקרא \u0003לבלבו.\u0004 ומכל מקום רואים מכאן שעכו אינה הקצה הצפוני של הארץ.","\u0003אמר אביי: רצועה נפקא\u0004 \u0005[יוצאת]\u0006 מעכו צפונה, ובה נמשך חלק של ארץ ישראל. ושואלים: \u0003ויהיב\u0004 \u0005[ו\u0006כי \u0005נותן]\u0006 ה\u0003תנא סימנא הכי\u0004 \u0005[סימן\u0006 באופן \u0005כזה]\u0006 לפי הדרך על גבולות הארץ? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 וכן \u0003קרא נמי יהיב סימנא\u0004 \u0005[הכתוב גם כן נותן סימן]\u0006 בדרך זו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמרו הנה חג ה' בשילו מימים ימימה אשר מצפונה לבית אל, מזרחה השמש למסלה העלה מבית אל שכמה, ומנגב ללבונה\"\u0004 (שופטים כא, יט), \u0003ואמר רב פפא:\u0004 יש להבין את הכתוב \"מזרחה השמש\" שכוונתו \u0003למזרחה של מסלה,\u0004 משמע שקובעים סימן לפי הדרך.","ומביאים סתירה בין שתי ברייתות, \u0003תנא חדא\u0004 \u0005[שנה\u0006 בברייתא \u0005אחת]:\u0006 \u0003המביא גט\u0004 שנכתב \u0003בספינה\u0004 בהיותה בארץ ישראל — הרי הוא \u0003כמביא בארץ ישראל\u0004 ואינו צריך לומר \"בפני נכתב ובפני נחתם\", \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 שהמביא גט שנכתב בספינה בהיותה בארץ ישראל — הרי הוא \u0003כמביא בחוצה\u0004 \u0003לארץ!\u0004","\u0003אמר ר' ירמיה, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ואפשר לומר כי \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, \u0003הא רבנן\u0004 \u0005[זו\u0006 כשיטת \u0005חכמים]\u0006 היא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עפר חוצה לארץ הבא בספינה לארץ\u0004 וצמח בו דבר — \u0003חייב במעשר ובשביעית,\u0004 משום שכאשר הוא מגיע לארץ — דינו כארץ ישראל, והרי הוא כצומח בארץ ישראל.","\u0003אמר ר' יהודה: אימתי\u0004 אמרו דבר זה? \u0003בזמן שהספינה גוששת,\u0004 שהיא שקועה עמוק במים ונוגעת באדמה, \u0003אבל\u0004 כש\u0003אין הספינה גוששת\u0004 — \u0003פטור.\u0004 ואם כן, החכם הסבור שהספינה היא כארץ ישראל סבור כדברי חכמים שספינה שבארץ ישראל דינה כארץ ישראל, והסבור שאין הספינה נדונה כארץ ישראל סבור כר' יהודה.","\u0003אביי אמר:\u0004 אפשר לומר כי \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כדעת \u0003ר' יהודה היא, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 בברייתא בה נפסק שדינה כחוצה לארץ — מדובר \u0003בזמן שאין הספינה גוששת, כאן\u0004 בברייתא בה שנינו שדינה כארץ ישראל — הרי זה \u0003בזמן שהספינה גוששת.\u0004","\u0003אמר ר' זירא:\u0004 אם היה \u0003עציץ נקוב המונח על גבי יתדות\u0004 וצמח בו דבר, בשאלה מה דינו, האם הצומח בו נחשב כצומח בארץ \u0003באנו למחלוקת ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 ביחס לאדמה שבספינה; שהרי לדעת חכמים אדמה זו למרות שאינה נוגעת ממש בארץ, נחשבת בכל זאת כמחוברת לארץ, ולדעת ר' יהודה, לא.","\u0003אמר רבא\u0004 ודחה: \u0003דילמא לא היא\u0004 \u0005[שמא אינו כן],\u0006 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם]\u0006 \u0003אלא בספינה,\u0004"],["\u0003העשויה לברוח\u0004 (לנוע ממקום למקום), כלומר, מפני שאינה קבועה במקום אחד, אפשר לומר שאין העפר שבה נחשב כמחובר לקרקע, \u0003אבל עציץ שאינו עשוי לברוח\u0004 ובדרך כלל הוא עומד במקום קבוע — \u0003לא,\u0004 ושמא אף בשאינו נוגע בקרקע, העפר שבתוכו נחשב כמחובר לה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר להיפך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אומרים חכמים שם]\u0006 שעפר שבספינה נחשב כארץ \u0003אלא\u0004 דווקא \u0003בספינה,\u0004 ש\u0003לא מפסיק אוירא\u0004 \u0005[האויר,\u0006 החלל\u0005]\u0006 בין האדמה שבספינה לבין הקרקע, \u0003דמיא כי ארעא סמיכתא דמיא\u0004 \u0005[ש\u0006כן \u0005המים כמו ארץ,\u0006 אדמה, \u0005סמיכה,\u0006 צבורה, הם \u0005נחשבים],\u0006 \u0003אבל עציץ\u0004 ש\u0003מפסיק אוירא\u0004 \u0005[האויר,\u0006 החלל\u0005] —\u0006 \u0003לא.\u0004","\u0003רב נחמן בר יצחק אמר: בנהרות\u0004 של \u0003ארץ ישראל\u0004 שספינה מהלכת בהם \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 בשתי הברייתות, \u0005אינם חלוקים]\u0006 שדין גט הנכתב בספינה כגט הנכתב בארץ ישראל. \u0003אלא כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003בים הגדול\u0004 (ים התיכון), והשאלה היתה האם הספינה שבו נחשבת כארץ ישראל, או לא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו ארץ ישראל ואיזהו חוצה לארץ?\u0004 — \u0003כל\u0004 התחום \u0003ששופע ויורד\u0004 בשיפוע ההר היורד \u0003מטורי אמנון\u0004 שבסוריה \u0003ולפנים\u0004 (דרומה), לכיוון ארץ ישראל — הרי הוא \u0003ארץ ישראל, מטורי אמנון ולחוץ\u0004 (צפונה) — הרי הוא \u0003חוצה לארץ. הנסין\u0004 \u0005[איים]\u0006 \u0003שבים\u0004 — \u0003רואין אותן כאילו חוט מתוח עליהם מטורי אמנון\u0004 בצפון \u0003עד נחל מצרים\u0004 בדרום, ומה שנמצא \u0003מן החוט ולפנים\u0004 (מזרחה) — הוא \u0003ארץ ישראל,\u0004 ומה שנמצא \u0003מן החוט ולחוץ\u0004 (מערבה) — הרי הוא \u0003חוצה לארץ,\u0004 זאת דעת חכמים.","ואילו \u0003ר' יהודה אומר: כל ש\u0004מכוון במישרין \u0003כנגד\u0004 (מול) \u0003ארץ ישראל\u0004 בים — \u0003הרי הוא כארץ ישראל\u0004 עצמה, \u0003שנאמר: \"וגבול ים, והיה לכם הים הגדול וגבול, זה יהיה לכם גבול ים\"\u0004 (במדבר לד, ו), ולפי זה כל מה שנמצא מכוון כנגד ארץ ישראל במערב ארץ ישראל הוא.","\u0003והנסין\u0004 \u0005[איים]\u0006 \u0003שבצדדין\u0004 שאינם מכוונים בדיוק בצפון ובדרום, \u0003רואין אותן כאילו חוט מתוח עליהן\u0004 בצפון \u0003מקפלוריא\u0004 שבטורי אמנון מערבה \u0003ועד ים אוקיינוס, ו\u0004בדרום \u0003מנחל מצרים\u0004 מערבה \u0003ועד ים אוקיינוס,\u0004 ומה שנמצא \u0003מן החוט ולפנים\u0004 — \u0003ארץ ישראל\u0004 הוא, \u0003מן החוט ולחוץ\u0004 — \u0003חוצה לארץ\u0004 הוא.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 שנאמר בו \u0003\"וגבול\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 שהרי מסתברים דברי ר' יהודה שגבול ארץ ישראל נכנס גם אל תוך הים. ומשיבים: \u0003מיבעי ליה לנסין\u0004 \u0005[\u0006הם \u0005צריכים אותו ל\u0006גבי ה\u0005איים]\u0006 שאף האיים נחשבים כמצויים בתוך גבול הארץ. \u0003ור' יהודה\u0004 סבור כי \u0003נסין לא צריכי קרא\u0004 \u0005[האיים אינם צריכים כתוב\u0006 מיוחד\u0005],\u0006 שפשוט לו שהם חלק מן הארץ.","שנינו במשנה ש\u0003ר' מאיר אומר: עכו\u0004 — \u0003כארץ ישראל\u0004 לגיטין. \u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מר' חייא בר אבא: המוכר עבדו לסוריא,\u0004 האם \u0003כמוכר\u0004 עבדו \u0003בחוצה לארץ דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ומשום כך, קונסים את הקונה שיוציאנו לחירות כדין המוכר עבדו לחוץ לארץ, \u0003או לא?\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 שאפשר להסיק את הדברים מן המשנה, ש\u0003ר' מאיר אומר: עכו\u0004 — \u0003כארץ ישראל לגיטין,\u0004 ונדייק מדבריו: \u0003לגיטין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003ל\u0004ענין \u0003עבדים\u0004 — \u0003לא,\u0004 \u0003וכל שכן סוריא דמרחקא טובא\u0004 \u0005[ש\u0006היא \u0005מרוחקת הרבה יותר\u0006\u0005],\u0006 מאשר עכו מארץ ישראל העיקרית, ולכן ודאי אין דינה כארץ ישראל והרי זה כמוכר עבדו לחוצה לארץ.","כיון שהזכרנו כאן את סוריה, מביאים מה ששנינו בתוספתא: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בשלשה דרכים שוותה סוריא לארץ ישראל, ובשלשה\u0004 שווה היא \u0003לחוצה לארץ. (סימן: ע\"ב ב\"ר ר\"ק).\u0004 ואלו הם הדברים בהם היא שווה לחוצה לארץ: \u0003עפרה טמא\u0004 — \u0003כ\u0004עפר \u0003חוצה לארץ, והמוכר עבדו לסוריא\u0004 — \u0003כמוכר\u0004 עבדו \u0003בחוצה לארץ\u0004 וחייב לשחררו. \u0003והמביא גט מסוריא\u0004 — \u0003כמביא מחוצה לארץ\u0004 וצריך לומר \"בפני נכתב ובפני נחתם\".","\u0003ובשלשה\u0004 דברים דומה היא \u0003לארץ ישראל: חייבת במעשר ובשביעית\u0004 — \u0003כארץ ישראל, והרוצה ליכנס לה בטהרה\u0004 — \u0003נכנס\u0004 כמו בארץ ישראל, \u0003והקונה שדה בסוריא\u0004 —"],["— \u0003כקונה בפרוארי\u0004 (שכונות סמוכות אל) \u0003ירושלים.\u0004 ומבארים את הדברים: \u0003חייבת במעשר ובשביעית כארץ ישראל\u0004 — \u0003קסבר\u0004 \u0005[סבור]\u0006 תנא זה: כי \u0003כיבוש יחיד שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003כיבוש,\u0004 ומאז שכבש דוד המלך את סוריה (\"כיבוש יחיד\") — נתקדשה בקדושת ארץ ישראל וחייבת במצוות הארץ.","ועל מה ששנינו בברייתא \u0003והרוצה ליכנס לה בטהרה\u0004 — \u0003נכנס,\u0004 תוהים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 ש\u0003עפרה טמא,\u0004 ואם כן, איך אפשר להיכנס אליה בטהרה? ומשיבים: הכוונה היא באפון שנכנס אליה כשהוא \u0003ב\u0004תוך \u0003שידה,\u0004 או \u0003תיבה,\u0004 או \u0003מגדל\u0004 (מיני ארונות), שכיון שאינו נוגע באדמה עצמה — הרי הוא טהור.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנכנס לארץ העמים\u0004 (חוצה לארץ) \u0003בשידה תיבה ומגדל\u0004 — \u0003רבי מטמא, ר' יוסי בר' יהודה מטהר. ואפילו רבי לא קא מטמא\u0004 \u0005[אינו מטמא]\u0006 את מי שאינו נוגע באדמה עצמה \u0003אלא\u0004 דווקא \u0003בארץ העמים,\u0004 ש\u0003גזרו\u0004 טומאה גם \u0003על גושה\u0004 (עפרה ממש) \u0003ו\u0004גם \u0003על אוירה\u0004 (החלל שלה), \u0003אבל סוריא\u0004 — לכל הדעות, \u0003על גושה\u0004 (עפרה עצמה) \u0003גזרו\u0004 טומאה, \u0003על אוירה לא גזרו,\u0004 ולכן אפשר להיכנס לסוריה בטהרה אם אינו נוגע בקרקע עצמה.","עוד שנינו בברייתא: \u0003והקונה שדה בסוריא\u0004 — \u0003כקונה בפרוארי ירושלים.\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר, מה אנו למדים מכאן הלכה למעשה? \u0003אמר רב ששת: לומר, שכותבין עליו,\u0004 על קנין זה, \u0003אונו\u0004 (שטר מכירה) \u0003ואפילו בשבת.\u0004","ותוהים: \u0003בשבת סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! כיצד התירו כתיבה בשבת, שהיא אב מלאכה וחייבים עליה סקילה! ומפרשים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבא\u0004 בענין דומה: \u0003אומר לגוי ועושה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא ש\u0003אומר לגוי\u0004 לכתוב שטר מכירה על קניה זו \u0003ועושה. ואף על גב\u0004 \u0005[ואף על פי]\u0006 שבדרך כלל \u0003אמירה לגוי שבות\u0004 שגזרו חכמים שלא לעשות דברים שונים משום שיש בהם פגיעה בשביתת השבת, וביניהם לומר לגוי שיעשה מלאכה אסורה בשבת עבור ישראל, והעובר על כך — עובר על דברי חכמים, מכל מקום כאן מכיון שיש בכך \u0003משום\u0004 מצוות \u0003ישוב ארץ ישראל\u0004 — \u0003לא גזור רבנן\u0004 \u0005[גזרו חכמים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עבד שהביא\u0004 את \u0003גיטו,\u0004 כלומר, את שטר שיחרורו, \u0003וכתוב בו\u0004 נוסח זה: \u0003\"עצמך ונכסיי קנויין לך\", עצמו\u0004 (את גופו) — \u0003קנה\u0004 בשטר זה, ונשתחרר, אבל את ה\u0003נכסים\u0004 — \u0003לא קנה\u0004 אלא אם כן יתקיים שטר זה בבית דין, כשאר שטרות על פי עדים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: אם היה כתוב בגט \u0003\"כל נכסיי קנויין לך\", מהו\u0004 הדין? \u0003אמר אביי: מתוך שקנה עצמו\u0004 כבן חורין, שהרי הוא בכלל הנכסים הנזכרים בשטר — \u0003קנה\u0004 גם את שאר ה\u0003נכסים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: בשלמא\u0004 \u0005[נניח]\u0006 את \u0003עצמו ליקני\u0004 \u0005[יקנה],\u0006 \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003גט אשה\u0004 שמתגרשת בגט שמביאה בידה, \u0003אלא\u0004 את ה\u0003נכסים לא ליקני\u0004 \u0005[יקנה],\u0006 \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 ב\u0003קיום שטרות דעלמא\u0004 \u0005[בכלל],\u0006 שאם אדם מביא שטר רגיל בענייני ממונות שאין לו קיום — אין סומכים על שטר זה. ואף כאן, כיון שאין קיום על שטר השיחרור ועל הכתוב בו — לא יקנה את הנכסים!","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר אביי\u0004 אחרי ששמע את דברי רבא: צריכים לומר להיפך, \u0003מתוך שלא קנה נכסים\u0004 — \u0003לא קנה\u0004 גם את \u0003עצמו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: בשלמא\u0004 \u0005[נניח]\u0006 שאת ה\u0003נכסים לא ליקני\u0004 \u0005[יקנה],\u0006 \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 ב\u0003קיום שטרות דעלמא\u0004 \u0005[בכלל],\u0006 \u0003אלא\u0004 את \u0003עצמו ליקני\u0004 \u0005[שיקנה]\u0006 \u0003מידי דהוה\u0004 \u0005[כפי שהוא\u0006 הדין\u0005]\u0006 ביחס ל\u0003גט אשה,\u0004 שהאשה יכולה להביא את גיטה ולהעיד עליו!","\u0003אלא אמר רבא: אחד זה ואחד זה,\u0004 בין שכתוב בנוסח \"עצמך ונכסיי\" ובין שכתוב בנוסח \"כל נכסיי\", \u0003עצמו\u0004 — \u0003קנה, נכסים\u0004 — \u0003לא קנה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לרבא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר דבר זה? \u0003כ\u0004דעת \u0003ר' שמעון, דאמר\u0004 \u0005[שאומר]\u0006 \u0003פלגינן דיבורא\u0004 \u0005[מחלקים אנו\u0006 את \u0005הדיבור]\u0006 שאף על פי שיש לפנינו שטר אחד או עדות אחת בנוסח כולל וסתמי, אין אנו רואים אותם כיחידה אחת מבחינה משפטית, אלא מחלקים — מקיימים חלק ומבטלים חלק.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו לעבדו\u0004 — \u0003יצא\u0004 העבד ונעשה \u0003בן חורין,\u0004 שהרי אף הוא בכלל הנכסים, אך אם \u0003שייר\u0004 לעצמו \u0003קרקע כל שהוא,\u0004 שלא נתן הכל לעבד — \u0003לא יצא\u0004 גם העבד \u0003בן חורין,\u0004 שאנו אומרים שכיון ששייר משהו, שמא גם את העבד עצמו שייר. \u0003ר' שמעון אומר:\u0004"],["\u0003לעולם\u0004 בכל נוסח שטר \u0003הוא בן חורין,\u0004 ואף אם שייר האדון קרקע לעצמו, \u0003עד שיאמר\u0004 בנוסח השטר \u0003\"כל נכסיי נתונין לפלוני עבדי חוץ מאחד מריבוא שבהן\",\u0004 שכיון שלא פירש מה שייר, שמא מה ששייר הוא העבד עצמו, ואם כן אין כאן שיחרור כלל. ומכל מקום רואים שלדעת ר' שמעון אנו מחלקים ומפרידים בנוסח הסתמי של השטר — \"כל נכסיי\", בין העבד לבין הנכסים, ומשום כך אף אם שייר האדון בנכסים — העבד משוחרר, וכדברי רבא.","ואולם כאן האם ניתן לקבל את שיטת ר' שמעון? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף בר מניומי אמר רב נחמן: אף על פי שקילס\u0004 (שיבח) \u0003ר' יוסי את ר' שמעון\u0004 בענין זה — מכל מקום \u0003הלכה כר' מאיר\u0004 שהוא התנא הראשון באותה משנה. ואגב כך מסבירים מה היה עניינו של קילוס זה; \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשנאמרו דברים\u0004 אלה שאמר ר' שמעון \u0003לפני ר' יוסי, קרא עליו המקרא הזה: \"שפתים ישק משיב דברים נכחים\"\u0004 (משלי כד, כו), אך למרות שבח זה אין הלכה כמותו!","לעצם ראייתו של רב אדא בר מתנה שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב נחמן הכי\u0004 \u0005[כך]\u0006 שאין מחלקים את הדיבור? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף בר מניומי אמר רב נחמן: שכיב מרע\u0004 (אדם הנוטה למות) \u0003שכתב כל נכסיו לעבדו ו\u0004אחרי כן \u0003עמד\u0004 (הבריא) מחוליו — \u0003חוזר בנכסים,\u0004 יכול לחזור בו ממה שנתן לעבד את הנכסים, \u0003ואינו חוזר ב\u0004מה ששיחרר את ה\u0003עבד.\u0004","ומסבירים: \u0003חוזר בנכסים\u0004 — שהרי \u0003מתנת שכיב מרע הוא,\u0004 ומתנת שכיב מרע לא ניתנה אלא מתוך הנחה שהוא לא יקום מחוליו, ואם קם מחוליו — כל מתנותיו בטלות, \u0003ו\u0004אולם \u0003אינו חוזר בעבד\u0004 — \u0003שהרי\u0004 כבר \u0003יצא עליו שם בן חורין!\u0004 אם כן, יוצא שאף רב נחמן מחלק בדיבור, שאותו דיבור עצמו מתקבל לדבר אחד ולא לדבר אחר.","\u0003אלא אמר רב אשי: התם\u0004 \u0005[שם]\u0006 שפסק רב נחמן כשיטת ר' מאיר, אין זה משום שלדעתו אין אנו מחלקים את הדיבור, ולא זה הנושא שנחלקו בו. אלא \u0003היינו טעמא\u0004 \u0005[זהו הטעם],\u0006 \u0003משום דלאו כרות גיטא הוא\u0004 \u0005[שאין זה גט הכורת\u0006 לגמרי\u0005],\u0006 שעל הגט לכרות ולנתק לגמרי את הזיקה שבין העבד לאדונו, וכיון שבתוך הגט עצמו שייר האדון לעצמו נכסים מסויימים, הרי אין הוא כורת לגמרי את הזיקה שביניהם. אבל לעצם השאלה האם מחלקים אנו בדיבור אחד — אף רב נחמן סבור כרבא.","שנינו במשנה ש\u0003אם יש עליו עוררין,\u0004 על הגט שהובא ממקום אחר בארץ ישראל, שם אין צורך לומר \"בפני נכתב\" וכו' — \u0003יתקיים בחותמיו,\u0004 על פי אימות חתימת העדים שבו. ושואלים: \u0003ערער\u0004 (ערעור) זה ב\u0003כמה?\u0004 כמה אנשים צריכים לערער כדי שנחשוש לו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ערער\u0004 הוא על ידי \u0003חד\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 שאומר שהגט מזוייף, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: דברי הכל אין ערער\u0004 על כל שטר \u0003פחות משנים!\u0004","\u0003אלא\u0004 אתה אומר ש\u0003ערער\u0004 הוא \u0003תרי\u0004 \u0005[שניים],\u0006 אם כן, הרי יש שניים שטוענים שהוא מזוייף, ושניים שמקיימים אותו, ונמצא כי \u0003תרי ותרי נינהו\u0004 \u0005[שניים ושניים הם]\u0006 שמעידים אלה כנגד אלה, ואם כן \u0003מאי חזית דסמכת אהני\u0004 \u0005[מה ראית שאתה סומך על אלה],\u0006 \u0003סמוך אהני\u0004 \u0005[על אלה]!\u0006 ומדוע אתה סומך יותר על העדים המקיימים אותו מאשר על העדים הבאים לפסול אותו? אלא יש לומר שאין מדובר פה בערעור על ידי אדם אחר, \u0003אלא\u0004 ה\u0003ערער\u0004 הוא של ה\u0003בעל\u0004 עצמו הטוען שהגט מזוייף.","שליח \u0003המביא גט ממדינת הים, ואינו יכול לומר \"בפני נכתב ובפני נחתם\", אם יש עליו,\u0004 על הגט, \u0003עדים\u0004 — \u0003יתקיים בחותמיו,\u0004 והם או מי שמכיר את חתימתם יאשרו אותו כדרך שמקיימים שאר שטרות.","\u0003אחד גיטי נשים ואחד\u0004 שטרות של \u0003שחרורי עבדים,\u0004 גם אלה וגם אלה, \u0003שוו\u0004 בהלכה \u0003למוליך ולמביא,\u0004 שצריך השליח המביאו ממדינת הים לארץ ישראל, או המוליכו מארץ ישראל למדינת הים, לומר שנכתב ונחתם בפניו, ונאמן על כך, \u0003וזו אחת מן הדרכים ששוו גיטי נשים לשחרורי עבדים.\u0004","דובר במשנה על מי שאינו יכול לומר \"בפני נכתב\"' ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו יכול לומר\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא \u0003חרש\u0004 ומשום כך אינו יכול לומר — דבר זה תמוה, וכי \u0003חרש בר אתויי גיטא\u0004 \u0005[בן הבאת גט]\u0006 \u0003הוא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכל כשרין להביא את הגט, חוץ מחרש שוטה וקטן!\u0004","\u0003אמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון ש\u0004השליח \u0003נתנו לה,\u0004 לאשה, \u0003כשהוא פיקח\u0004 והשליחות נעשתה כדין, \u0003ולא הספיק לומר \"בפני נכתב ובפני נחתם\" עד שנתחרש,\u0004 ומשום כך אינו יכול לומר.","שנינו במשנה ש\u0003אחד גיטי נשים ואחד שיחרורי עבדים\u0004 שווים לענין שליח המביא אותם ממדינת הים לארץ ישראל או ממנה למדינת הים שצריך לומר \"בפני נכתב\" וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בשלשה דרכים שוו גיטי נשים לשיחרורי עבדים: שוו למוליך ולמביא,\u0004 שאם מוליך גט למדינת הים או מביא אותו משם, צריך להעיד שבפניו נכתב ונחתם. ועוד: \u0003וכל גט\u0004 (שטר) \u0003שיש עליו\u0004 חתימתו של \u0003עד כותי\u0004 — הרי זה שטר \u0003פסול, חוץ מגיטי נשים ושחרורי עבדים\u0004 שאף עד כזה כשר בהם. \u0003וכל השטרות\u0004"],["\u0003העולים בערכאות\u0004 (הנעשים בבתי משפט) \u0003של גוים, אף על פי שחותמיהן גוים\u0004 — הריהם \u0003כשירין, חוץ מגיטי נשים ושחרורי עבדים\u0004 שאינם כשרים כשנעשו על ידי גויים, אלא רק על ידי ישראל. \u0003ו\u0004אם נסבור אף \u0003כדברי ר' מאיר\u0004 אם כן שווים גיטין של נשים ושחרורי עבדים \u0003בארבעה\u0004 דברים, והם השלושה האמורים מקודם, ועוד שבעל \u0003האומר: \"תן גט זה לאשתי\", ו\u0004כן אדון האומר: \u0003\"\u0004תן \u0003שטר שחרור זה לעבדי\",\u0004 אם \u0003רצה לחזור בשניהם\u0004 קודם שהגיעו לידי האשה או העבד — \u0003יחזור,\u0004 אלו \u0003דברי ר' מאיר.\u0004","על סגנון הדברים שואלים: \u0003בשלמא לרבנן\u0004 \u0005[נניח לחכמים],\u0006 \u0003מנינא\u0004 \u0005[המנין]\u0006 שמנו בראשית דבריהם \"שלושה דברים\" בא \u0003למעוטי הא\u0004 \u0005[למעט\u0006 את \u0005זו]\u0006 שאמר \u0003ר' מאיר,\u0004 והדגישו שדווקא בשלושה ולא בארבעה. \u0003אלא לר' מאיר, מנינא למעוטי מאי\u0004 \u0005[המנין למעט\u0006 את \u0005מה]\u0006 הוא בא? מדוע הוצרך לומר \"בארבעה\" דברים, והלא די היה לומר שר' מאיר מוסיף גם דבר זה!","ומשיבים: \u0003למעוטי הא\u0004 \u0005[למעט\u0006 את \u0005זו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עדים שאין יודעים לחתום\u0004 (שאינם יודעים לכתוב את שמם), \u0003מקרעין להם נייר חלק,\u0004 שמניחים נייר על גבי השטר, ובנייר זה עושים קרעים = חתכים של אותיות שמם \u0003ו\u0004הם \u0003ממלאים את הקרעים\u0004 ב\u0003דיו\u0004 וכך הם חותמים את שמם.","\u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בגיטי נשים,\u0004 בהם עושים דבר זה, \u0003אבל שחרורי עבדים ושאר כל השטרות, אם יודעין\u0004 העדים \u0003לקרות ולחתום\u0004 — \u0003חותמין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין חותמין.\u0004 וכך גם לדעת ר' מאיר, אין גיטי נשים ושחרורי עבדים שווים בדבר זה, ואת דבר זה בא המנין \"ארבעה\" למעט.","ולעצם דברי רבן שמעון בן גמליאל תוהים: \u0003קרייה מאן דכר שמיה\u0004 \u0005[קריאה מי הזכיר\u0006 את \u0005שמה]?\u0006 שהרי קודם לא דיברנו אם העדים יודעים לקרוא, אלא רק על ידיעתם לחתום, ומדוע בא רבן שמעון בן גמליאל לדבר על יכולת קריאה? ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003עדים שאין יודעין לקרות\u0004 — \u0003קורין לפניהם\u0004 את השטר \u0003ו\u0004הם \u0003חותמין, ושאין יודעין לחתום\u0004 — \u0003מקרעין להם.\u0004 ואז מובנים דברי רבן שמעון בן גמליאל.","ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 דברים שבהם שווים גיטי נשים ושחרורי עבדים \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 גם דבר זה ששנינו: שכיב מרע \u0003האומר \"תנו גט זה לאשתי\"\u0004 או שאמר \u0003\"\u0004תנו \u0003שטר שחרור זה לעבדי\", ומת\u0004 — \u0003לא יתנו לאחר מיתה,\u0004 אבל אם אמר \u0003\"תנו מנה לפלוני\", ומת\u0004 — \u0003יתנו לאחר מיתה.\u0004 נמצא שיש דבר שווה בגיטין ובשחרורי עבדים נוסף למה ששנינו!","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 את הדברים השווים לגיטי נשים ולשחרורי עבדים, שנה דווקא \u0003מילתא דליתיה\u0004 \u0005[דבר שאינו]\u0006 קיים \u0003בשטרות\u0004 אחרים, אבל \u0003מילתא דאיתיה\u0004 \u0005[דבר שישנו]\u0006 גם \u0003בשטרות\u0004 אחרים \u0003לא קתני\u0004 \u0005[שנה].\u0006","ודין זה שאין נותנים לאחר מיתה קיים גם בשטרות אחרים, שכך מצינו ש\u0003שלח רבין\u0004 מארץ ישראל \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אבהו: הוו יודעין ששלח ר' אלעזר לגולה\u0004 (לבבל) \u0003משום\u0004 (משמו של) \u0003רבינו\u0004 (ר' יוחנן): \u0003שכיב מרע שאמר \"כתבו ותנו מנה לפלוני\", ומת\u0004 האיש לפני שהספיקו לכתוב שטר — \u0003אין כותבין ונותנין.\u0004 ומדוע?","\u0003שמא לא גמר\u0004 בליבו \u0003להקנותו\u0004 למנה זה \u0003אלא בשטר, ואין שטר לאחר מיתה.\u0004 משמע שגם בשטרות אחרים אין שטר לאחר מיתה, ואין זה מיוחד לגיטי נשים ושחרורי עבדים, ולכן לא נמנה בין הדברים שהם שווים בהם.","ומקשים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 דין נוסף שווה לגיטי נשים ושחרורי עבדים, שצריך שייכתבו גט אשה ושטר שחרור \u0003לשמה,\u0004 דווקא עבור זה שנועד לו, ולא לאחר, ומדוע דין זה לא נכלל בין הדברים השווים לגיטי נשים ולשחרורי עבדים?","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבה, היינו\u0004 \u0005[זהו]\u0006 מה שאמרו: שוו ל\u0003מוליך ומביא,\u0004 שהרי לשיטתו עניין לשמה הוא הטעם העיקרי לצורך שיאמרו העדים \"בפני נכתב\" וכו', ואם כן, זה הוא בעצם הדין של כתיבה לשמה. \u0003אלא ל\u0004שיטת \u0003רבא\u0004 הסבור שהטעם אינו אלא משום הצורך לקיים את הגט, \u0003קשיא\u0004 \u0005[קשה]!\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003בין לרבה בין לרבא האיכא\u0004 \u0005[הרי יש]\u0006 פסול \u0003מחובר,\u0004 שאם היה גט אשה או שחרור עבד כתוב (וחתום) בהיותו מחובר לקרקע, אינו כשר! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר\u0006 הוא \u0005שנה\u0006 שם\u0005]\u0006 הרי זה רק דברים שהם \u0003פסולא דרבנן\u0004 \u0005[פסול שמדברי סופרים],\u0006 ואולם פסול \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003לא קתני\u0004 \u0005[אינו שונה]\u0006 וכיון שפסול לשמה ופסול מחובר הריהם מן התורה, לא שנה אותו בין הדברים הללו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ערכאות של גוים דפסולא דאורייתא\u0004 \u0005[שפסול שמן התורה]\u0006 \u0003הוא, וקתני\u0004 \u0005[ו\u0006הוא \u0005שונה\u0006 אותו\u0005]!\u0006 ומשיבים: צריך לומר שניתן הגט \u0003בעדי מסירה\u0004 כשרים, \u0003וכ\u0004דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 כלומר, הם עיקרו של מעשה הגירושין, שלשיטתו חתימת הגט אינה עיקר, אלא מסירתו בעדים. ומשום כך פסול של גט שנחתם בערכאות של גויים אינו אלא מדברי חכמים.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ש\u0006הוא \u0005שונה בסופה]\u0006 של אותה הלכה, במשנה להלן, \u0003ר' שמעון אומר: אף אלו,\u0004 גיטי נשים ושחרורי עבדים, \u0003כשירין, ואמר ר' זירא: ירד\u0004 (קיבל) \u0003ר' שמעון לשיטתו של ר' אלעזר,\u0004 ש\u0003אמר עדי מסירה כרתי\u0004 \u0005[כורתים]\u0006 ומשום כך התיר שטרות אלה שנעשו בערכאות של גויים, \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר לא\u0004 כך, אלא סבור שעדי חתימה הם העיקר, ובכל זאת מנה פסול זה של גיטין שנעשו בערכאות של גויים, אף שהוא פסול שמן התורה!"],["ודוחים: אפשר לומר כי גם התנא הראשון סבור כר' אלעזר שעדי מסירה הם עיקר תוקפו של הגט, ומכל מקום \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 כשהיו החתימות שבגט \u0003שמות מובהקין\u0004 של גויים. שהתנא הראשון סבור שלמרות שמעיקר הדין כשר הגט אם יימסר בעדים כשרים, מכל מקום יש לחשוש שמא ימסרנו בפני אותם עדים גויים שחתמו עליו, ולכן פסל אותו, בגזירה מדברי חכמים. ואילו ר' שמעון סבור שאם היו בו שמות מובהקים של גויים, אין מקום לגזירה זו, שכיון שיודעים שאין הם עדים כשרים בודאי ימסרו את הגט בפני עדים כשרים, ויהא הגט כשר אם נמסר כדין.","ומקשים עוד: \u0003והא\u0004 \u0005[והרי]\u0006 דין \u0003חזרה,\u0004 שלדעת ר' מאיר יכול לחזור הבעל מן הגט או האדון מן השחרור ובטלה השליחות ואין הם חלים — הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003וקתני\u0004 \u0005[ושנה]\u0006 אותו בין הדברים ששוו בהם גיטין ושחרורים, משמע שאינו מחלק בין דברים שהם מן התורה או מדברי סופרים!","\u0003אלא,\u0004 צריך לחזור מן ההסבר שאמרנו, ולומר באופן אחר: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 דברים שווים — שנה \u0003מילתא דליתא\u0004 \u0005[דבר שאינו]\u0006 קיים גם \u0003ב\u0004דיני \u0003קידושין,\u0004 ואולם \u0003מילתא דאיתא\u0004 \u0005[דבר שישנו]\u0006 \u0003בקידושין\u0004 — \u0003לא קתני\u0004 \u0005[שנה].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חזרה גופה\u0004 \u0005[עצמה]\u0006 גם כן \u0003איתא\u0004 \u0005[ישנה]\u0006 \u0003בקידושין,\u0004 שאם שלח שליח ובידו שטר אירוסין עבור אשה, יכול לחזור בו! ואומרים: מדובר כאן \u0003בשליחות בעל כורחה,\u0004 ששלח לעשות דבר שאין המקבל רוצה בו, כגון שמקדש אשה בעל כורחה, או משחרר העבד שלא ברצונו ש\u0003בגירושין איתא\u0004 \u0005[ישנו]\u0006 דבר זה, שאין הגט צריך להינתן מרצונה של האשה, \u0003ובקידושין ליתא\u0004 \u0005[אינו],\u0006 שאין אשה מתקדשת אלא מדעתה.","\u0003כל גט שיש עליו עד כותי\u0004 (שומרוני) — \u0003פסול, חוץ מגיטי נשים ושחרורי עבדים. מעשה שהביאו לפני רבן גמליאל לכפר עותנאי גט אשה, והיו עדיו עדי כותים, והכשיר.\u0004","ושואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כדעת \u0005מי היא משנתנו\u0006 זו\u0005]?\u0006 הרי אינה \u0003לא\u0004 כדעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 \u0003ולא\u0004 כדעת \u0003ר' אלעזר, ולא\u0004 כדעת \u0003רבן שמעון בן גמליאל,\u0004 בברייתא המובאת להלן.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצת כותי\u0004 — \u0003מותרת\u0004 באכילה בפסח ואין בה חשש חמץ, \u0003ואדם\u0004 מישראל אפילו \u0003יוצא בה ידי חובתו\u0004 של אכילת מצת מצוה \u0003בפסח.\u0004 \u0003ר' אלעזר אוסר\u0004 מצת כותי, \u0003לפי שאין\u0004 הכותים \u0003בקיאין בדקדוקי מצות. רבן שמעון בן גמליאל אומר: כל מצוה שהחזיקו בה כותים\u0004 אין לחשוש שאינם בקיאים בה, אלא להיפך הם \u0003הרבה מדקדקין בה,\u0004 ואפילו \u0003יותר מישראל.\u0004","ומעתה נברר: משנתנו \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כדעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שבברייתא, אם כן \u0003אפילו שאר שטרות נמי\u0004 \u0005[גם כן]\u0006 כשרים בעד כותי, שהרי אם הוא מתיר מצת כותים משמע שהוא מחשיב את הכותים כישראל, ואם כן יש לחשבם כישראל גם לגבי עדות בשטרות מכל סוג! \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' אלעזר\u0004 שהוא חושש שאין הכותים בקיאים בדקדוקי מצוות, אם כן \u0003אפילו גט אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יכשיר בעדות כותי!","\u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003רבן שמעון בן גמליאל,\u0004 יש לברר: \u0003אי דאחזוק\u0004 \u0005[אם שהחזיקו]\u0006 במצוה זו ומקיימים אותה — \u0003אפילו\u0004 ב\u0003שאר שטרות נמי\u0004 \u0005[גם כן]\u0006 אפשר יהיה לסמוך עליהם, \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא אחזוק\u0004 \u0005[החזיקו]\u0006 בה\u0005,\u0006 אם כן \u0003אפילו גט אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נכשיר בעדותם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי משנתנו שיטת \u0003רבן שמעון בן גמליאל היא, ו\u0004אולם מדובר באופן \u0003דאחזוק בהא\u0004 \u0005[שהחזיקו בזה],\u0006 בגיטי נשים, \u0003ולא אחזוק בהא\u0004 \u0005[החזיקו בזה],\u0006 בשאר שטרות\u0005,\u0006 אולם \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהחזיקו בגיטי נשים ומדקדקים בהם, אם כן, \u0003מאי איריא חד\u0004 \u0005[מדוע דווקא\u0006 כשר רק עד \u0005אחד]\u0006 כותי? \u0003אפילו תרי נמי\u0004 \u0005[שניים גם כן]!\u0006 \u0003אלמה\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 \u0003אמר ר' אלעזר: לא הכשירו בו,\u0004 בגט אשה, \u0003אלא עד אחד כותי בלבד?\u0004","ומשיבים: \u0003לעולם\u0004 תפרש שמשנתנו כדעת \u0003ר' אלעזר\u0004 היא, שבדרך כלל אין סומכים על כותי, \u0003ו\u0004אולם במשנתנו מדובר \u0003כגון דחתים\u0004 \u0005[שחתום]\u0006 \u0003ישראל לבסוף,\u0004"],["\u0003דאי לאו\u0004 \u0005[שאם לא]\u0006 ש\u0003כותי חבר הוה\u0004 \u0005[היה]\u0006 שקיבל עליו לשמור מצוות ולדקדק בהן, \u0003לא\u0004 היה אותו ישראל \u0003מחתים ליה מקמיה\u0004 \u0005[אותו לפניו].\u0006 ובמקרה הזה אפשר לסמוך על עד כותי זה, למרות שסתם כותי אין סומכים עליו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבמקרה כזה מדובר, אם כן \u0003אפילו שאר שטרות נמי\u0004 \u0005[גם כן]\u0006 אפשר יהיה להכשיר, אם עד ישראל חתום בסוף!","\u0003אלא\u0004 אין הדין כך משום ש\u0003אמרינן\u0004 \u0005[אנו אומרים]\u0006 שאין זו ראיה שהיה זה כותי חבר, ושמא חתום היהודי למטה כי \u0003רווחא שבק למאן דקשיש מיניה\u0004 \u0005[רווח השאיר למי שזקן ממנו],\u0006 שבשעה שחתם חשב שיחתום לפניו אדם אחר גדול ממנו, ולבסוף בא הכותי וחתם, ולכן אין לסמוך על כך, ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בגט, אפשר לומר ש\u0003רווחא שבק למאן דקשיש מיניה\u0004 \u0005[רווח השאיר למי שזקן ממנו]\u0006 ומדוע נכשיר במקרה כזה גט ושחרור ולא שטרות אחרים!","\u0003אמר רב פפא, זאת אומרת,\u0004 מכאן אפשר ללמוד כי \u0003עדי הגט אין חותמין זה בלא זה,\u0004 כלומר, זה שלא בפני זה. ומפני שהם צריכים לחתום יחד, רואה העד היהודי שכותי הוא זה החותם עימו, ואם הניחו לחתום לפניו בוודאי יודע בו שהוא כשר, ומשום כך חתם גם הוא. אבל בשטרות אחרים שאין העדים צריכים לחתום בבת אחת, אי אפשר לסמוך על העד הכותי.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שבגט אין העדים חותמים זה בלא זה? \u0003אמר רב אשי: גזירה\u0004 היא, \u0003משום\u0004 האומר: \u0003\"כולכם\u0004 היו עדים על גט זה \u0003\".\u0004 שאז צריך שכולם יחתמו יחד ואם לא יעשו כן אין הגט כשר, ומשום כך גזרו שבכל מקרה יחתמו עדי הגט יחד.","כיון שהזכרנו את ההלכה של ר' אלעזר, באים לדון בה \u0003גופא\u0004 \u0005[עצמה],\u0006 \u0003אמר ר' אלעזר: לא הכשירו בו,\u0004 בגט אשה, \u0003אלא עד אחד כותי בלבד\u0004 מתוך עדיו. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]?\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה, שהרי נאמר במשנה: \u0003כל גט שיש עליו עד כותי\u0004 — \u0003פסול\u0004 חוץ מגיטי נשים ושחרורי עבדים, משמע: עד אחד ולא שניים!","ודוחים: \u0003אי ממתניתין\u0004 \u0005[אם ממשנתנו]\u0006 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו תרי נמי\u0004 \u0005[שניים\u0006 בגט \u0005גם כן]\u0006 כשרים, \u0003והאי דקתני חד\u0004 \u0005[וזה ש\u0006הוא \u0005שונה אחד]\u0006 — הרי זה כדי להדגיש את ההבדל, \u0003משום\u0004 ש\u0003בשטרות אפילו חד נמי\u0004 \u0005[אחד גם כן]\u0006 \u0003לא\u0004 כשר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' אלעזר שאף בגיטין רק אחד כשר ולא יותר.","ושואלים: \u0003ותרי\u0004 \u0005[ושניים],\u0006 שני עדים כותים, \u0003לא? והא קתני\u0004 \u0005[והרי\u0006 הוא \u0005שונה]\u0006 במשנתנו במפורש: \u0003מעשה והביאו לפני רבן גמליאל לכפר עותנאי גט אשה, והיו עדיו עדי כותים והכשיר! אמר אביי, תני\u0004 \u0005[שנה]\u0006 שם: לא \"עדיו\" אלא \u0003\"עדו\",\u0004 שלא הכשיר רבן גמליאל את הגט אלא בחתימתו של עד כותי אחד ואכן בשנים אף הוא אינו מכשיר.","\u0003רבא אמר: לעולם\u0004 תשנה שם \u0003תרי\u0004 \u0005[שניים],\u0006 \u0003ו\u0004אלא \u0003רבן גמליאל מיפלג פליג\u0004 \u0005[חולק]\u0006 על חכמים, \u0003וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003ורבן גמליאל מכשיר\u0004 אפילו \u0003בשנים, ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003שהביאו לפני רבן גמליאל לכפר עותנאי גט אשה, והיו עדיו עדי כותים והכשיר.\u0004","\u0003כל השטרות העולים בערכאות\u0004 (הנעשים בבתי משפט) \u0003של גוים\u0004, \u0003אף על פי שחותמיהם גוים\u0004 — כולם \u0003כשירים\u0004 לכל ענין שבהלכה, \u0003חוץ מגיטי נשים ושחרורי עבדים. ר' שמעון אומר: אף אלו כשירין,\u0004 ו\u0003לא הוזכרו\u0004 בבית המדרש ששטרות של גויים פסולים \u0003אלא בזמן שנעשו בהדיוט\u0004 (על ידי אדם פשוט) ולא בבית משפט.","במשנה שנינו שכל השטרות שנכתבו בערכאות של גויים כשרים, ומעירים: התנא \u0003קא פסיק ותני\u0004 \u0005[פוסק,\u0006 קובע \u0005ושונה\u0006 במשנתנו\u0005]\u0006 הלכה כללית, \u0003לא שנא\u0004 \u0005[שונה]\u0006 הדבר ב\u0003מכר ולא שנא\u0004 \u0005[שונה]\u0006 ב\u0003מתנה,\u0004 שבכל מקרה כשר.","ויש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מכר,\u0004 מובן הדבר, שכן כבר \u0003מכי יהיב זוזי קמייהו\u0004 \u0005משעה שנתן\u0006 הקונה \u0005כסף\u0006 למוכר \u0005לפניהם,\u0006 לפני הדיינים הגויים\u0005]\u0006 \u0003הוא\u0004 ש\u0003קנה\u0004 שנעשה הקנין, \u0003ושטרא\u0004 \u0005[והשטר]\u0006 \u0003ראיה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 לכך שהיה קנין, משום \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא יהיב זוזי קמייהו\u0004 \u0005[\u0006היה \u0005נותן\u0006 את \u0005הכסף לפניהם]\u0006 \u0003לא הוו מרעי נפשייהו\u0004 \u0003וכתבין ליה שטרא\u0004 \u0005[היו מריעים,\u0006 מזיקים, \u0005לעצמם,\u0006 לשמם הטוב \u0005וכותבים לו\u0006 את \u0005השטר],\u0006 ואם כן, השטר אינו אלא שטר ראיה הגון לקנין שנעשה כדין.","\u0003אלא מתנה במאי קא קני\u0004 \u0005[במה\u0006 המקבל \u0005קונה]\u0006 אותה מן הנותן — \u0003לאו בהאי שטרא\u0004 \u0005[האם לא בשטר זה]?\u0006 \u0003ו\u0004אולם \u0003האי שטרא חספא בעלמא\u0004 \u0005[שטר זה חרס סתם]\u0006 \u0003הוא,\u0004 ששטר שנכתב על ידי גויים אין לו דין של שטר מבחינת דיני ישראל! \u0003אמר שמואל: דינא דמלכותא\u0004 \u0005[דין המלכות]\u0006 — \u0003דינא\u0004 \u0005[דין ]\u0006 הוא\u0005,\u0006 ולכן לכל העניינים השייכים להעברת נכסים יש תוקף גם להלכה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 כך במשנתנו: לא \"כל השטרות העולים בערכאות של גוים כשרים חוץ מגיטי נשים\", אלא \u0003\"חוץ מכגיטי נשים\".\u0004 שיש להבחין בין שטרות שונים: שטרות שאינם אלא לראיה — כשרים אף אם נעשו בערכאות של גויים, ואילו שטרות שהם עצמם יוצרים את המעשה המשפטי, כמו גיטי נשים — הריהם פסולים אם נעשו בערכאות של גויים.","שנינו במשנה ש\u0003ר' שמעון אומר: אף אלו,\u0004 גיטי נשים, \u0003כשירין\u0004 אם נעשו בערכאות של גויים וחתמו עליהם עדים גויים. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 גויים \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני כריתות נינהו\u0004 \u0005[הם],\u0006 וכיון שאינם בכלל עניינו של גט ושל כריתות הכתובים בתורה, כיצד יכולים הם לחתום על גט?","\u0003אמר ר' זירא: ירד\u0004 (הלך) \u0003ר' שמעון לשיטתו של ר' אלעזר,\u0004 ש\u0003אמר עדי מסירה כרתי\u0004 \u0005[כורתים,\u0006 גומרים\u0005]\u0006 את הגירושין, ומשום כך חתימת הגט אינה עיקרו של הגט, אלא מסירתו, ולכן אין מתחשבים בחותמיו.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא:\u0004 אף שר' אלעזר מכשיר גט בלא שני עדים, מכל מקום \u0003מודה ר' אלעזר ב\u0004גט ה\u0003מזויף מתוכו\u0004 שיש פגם בעצם העדות שבו, \u0003ש\u0004הוא \u0003פסול,\u0004 אף שנמסר כדין, מחשש שמא יבואו לסמוך על אותם עדים כעדי מסירה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 —"],["\u0003בשמות מובהקין\u0004 של גויים, שבהם אין כל חשש של \"מזוייף מתוכו\" שיבואו לסמוך על עדים אלה כעדי מסירה, כיון שברור לכל שגויים הם.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 הם \u0005בדיוק]\u0006 \u0003שמות מובהקין? אמר רב פפא:\u0004 שמות \u0003כגון: הורמיז, ואבודינא, בר שיבתאי, ובר קידרי, ובאטי, ונקים אונא.\u0004","ושואלים, לפי שיטה זו יש לדייק: \u0003אבל\u0004 אם נחתמו גיטין על ידי עדים גוים בעלי \u0003שמות שאין\u0004 הם שמות \u0003מובהקים\u0004 של גויים \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין — האם \u0003לא\u0004 יהא זה גט? \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006ר' שמעון \u0005שונה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003לא הוזכרו\u0004 גיטין ושחרורי עבדים להיפסל \u0003אלא בזמן שנעשו בהדיוט,\u0004 אבל לא כן הדין בערכאות, \u0003לפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה\u0006 \u0005עצמה\u0006 בערכאות\u0005],\u0006 חלוקה יותר מדוקדקת: \u0003במה דברים אמורים\u0004 שכשחתמו בגט עדים גוים הרי זה כשר — \u0003בשמות מובהקין, אבל שמות שאין מובהקין\u0004 — \u0003לא!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כך צריכים להבין את דברי ר' שמעון, שאף אלו (גיטין ושחרורים) כשרים, \u0003במה דברים אמורים\u0004 — \u0003בשמות מובהקין, אבל בשמות שאין מובהקין, נעשה\u0004 הדבר \u0003כמי שנעשו\u0004 שטרות אלה \u0003בהדיוט ופסולין.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף\u0006 המשנה\u0005]\u0006 אין אנו ממשיכים בענין גיטי נשים, אלא \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003לגיטי\u0004 (שטרות) \u0003ממון,\u0004 ואין זה מדברי ר' שמעון, אלא חוזר לדברי חכמים, \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003לא הוזכרו גיטי ממון\u0004 ש\u0003פסולים אלא בזמן שנעשו בהדיוט,\u0004 אבל כשנעשו בערכאות — הרי הם כשרים.","וכהעמדה זאת של דברי חכמים \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' אלעזר בר' יוסי, כך אמר ר' שמעון לחכמים ב\u0004עיר \u0003צידן: לא נחלקו ר' עקיבא וחכמים על כל השטרות העולין בערכאות של גוים, שאף על פי שחותמיהן גוים\u0004 — \u0003כשרים\u0004 הם, \u0003ואפילו גיטי נשים ושחרורי עבדים. לא נחלקו אלא בזמן שנעשו בהדיוט,\u0004 שלא בבית דין גמור, \u0003שר' עקיבא מכשיר, וחכמים פוסלים חוץ מגיטי נשים ושחרורי עבדים.\u0004","\u0003רבן שמעון בן גמליאל אומר: אף אלו,\u0004 גיטי נשים ושחרורי עבדים, \u0003כשירין במקום שאין ישראל חותמין,\u0004 שאין הגויים מניחים לעדים יהודים לחתום, והכל יודעים ששטרות של גויים אינם חתומים על ידי יהודים. \u0003אבל במקום שישראל חותמין\u0004 — \u0003לא,\u0004 משום שאפשר לטעות ולחשוב שישראל הם שחתמו על הגט הזה, ויבואו למסור אותו בפני אותם עדים, שלאמיתו של דבר הם גויים, ואין הגירושין חלים.","ושואלים: ב\u0003מקום שאין ישראל חותמין נמי ליגזור\u0004 \u0005[גם כן נגזור]\u0006 \u0003אטו\u0004 \u0005[משום]\u0006 \u0003מקום שישראל חותמין!\u0004 ומשיבים: \u0003שמא בשמא מחליף\u0004 \u0005[שם בשם\u0006 עלול \u0005להתחלף],\u0006 ופעמים סבורים שהוא יהודי אף ששמו הוא שם מובהק של גוי, אבל \u0003אתרא באתרא לא מחליף\u0004 \u0005[מקום במקום אינו\u0006 עלול \u0005להתחלף]\u0006 ויודעים הכל שבמקום הזה כל החתימות הם של גויים, ודואגים למסור את הגט שלא בפני החתומים עליו, אלא בעדים ישראלים.","מסופר כי \u0003רבינא סבר לאכשורי בכנופיאתה דארמאי\u0004 \u0005[חשב להכשיר\u0006 שטר שנכתב \u0005על ידי חבורה של גויים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רפרם: \"ערכאות\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 שאין שטרות של גויים כשרים אלא אם נעשה הדבר בבית משפט חשוב, ולא בחבורה כלשהי.","ובענין דומה \u0003אמר רבא: האי שטרא פרסאה\u0004 \u0005[שטר פרסי זה]\u0006 שנכתב על ידי השלטונות הפרסים \u0003דמסריה ניהליה באפי סהדי\u0004 \u0005[שמסר אותו לו,\u0006 \u0003למקבל\u0004 \u0005בפני עדי]\u0006 \u0003ישראל\u0004 — \u0003מגבינן\u0004 \u0005[מגבים אנו],\u0006 בית דין מתיר לגבות, \u0003ביה\u0004 \u0005[בו]\u0006 \u0003מ\u0004נכסים \u0003בני חרי\u0004 \u0005[חורין].\u0006 שאף על פי שאין דינו כשטר ממש, לגבות בו גם מנכסים משועבדים, מכל מקום העובדות שבשטר נחשבות כבדוקות, ומשום כך אפשר לסמוך עליו לפחות לגבות בו מנכסים שאינם משועבדים.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 העדים על מסירת השטר הזה \u0003לא ידעי למיקרא\u0004 \u0005[אינם יודעים לקרוא],\u0006 שאינם מבינים פרסית, ואם כן, כיצד אפשר לסמוך על מה שכתוב בו? ומשיבים: מדובר פה \u0003בדידעי\u0004 \u0005[בש\u0006 העדים \u0005יודעים]\u0006 לקרוא.","ושואלים: \u0003והא בעינא\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה בשטר \u0003כתב שאינו יכול לזייף, וליכא\u0004 \u0005[ואין כאן]\u0006 דבר זה, כיון שאין הפרסים מקפידים על זה! ומשיבים: מדובר כאן \u0003בדאפיצן\u0004 \u0005[ב\u0006קלף \u0005שמעובד בעפצים]\u0006 ואינו ניתן לזיוף. ושואלים עוד: \u0003והא בעינא\u0004 \u0005[והרי צריכים אנו]\u0006 את מה שנאמר בהלכות שטרות: \u0003צריך שיחזיר מענינו של שטר בשיטה אחרונה,\u0004 ששטר שנכתב כדין צריך שבשורה האחרונה שבו תהיה חזרה על עיקר עניינו של השטר, כדי לברר שלא היתה טעות בחלקו הראשון, \u0003וליכא\u0004 \u0005[ואין\u0006 דבר \u0005זה]\u0006 בשטרות פרסיים! ומשיבים: \u0003בדמהדר\u0004 \u0005[בשחזרו\u0006 עליו\u0005],\u0006 שנוסח השטר היה כזה שחזרו בשורה האחרונה על עיקרו של השטר.","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ממשעבדי נמי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים גם כן]\u0006 יגבה, שהרי שטר זה הוא בכל ענייניו כשטר שכותבים ישראל, ומדוע נאמר שאינו גובה בו אף מן המשועבדים? ומשיבים: מכל מקום \u0003לית ליה קלא\u0004 \u0005[אין לו קול],\u0006 כלומר, אינו מפורסם ברבים. כי דבר שנעשה בערכאות ובכתב של פרסים אין ישראל שומעים עליו, ומשום כך הוא נחשב כמילווה בעל פה שאין לו קול וגובה רק מנכסים בני חורין, אבל לא ממשועבדים.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן:\u0004"],["\u0003עדים החתומין על הגט ושמותן כשמות גוים, מהו\u0004 דינו של גט זה ומה עושים בדבר זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא בא לידינו\u0004 למעשה \u0003אלא\u0004 גיטין שעליהם היו חתומים שמות, כגון \u0003לוקוס ולוס, והכשרנו\u0004 אותם על ידי עדי מסירה כשרים.","ומדייקים: \u0003ודוקא לוקוס ולוס,\u0004 ש\u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003ישראל דמסקי בשמהתייהו\u0004 \u0005[שנקראים בשמותיהם],\u0006 \u0003אבל שמהתא אחריני דשכיחי\u0004 \u0005[שמות אחרים\u0006 של גויים, \u0005שמצויים]\u0006 גם \u0003ישראל דמסקי בשמהתייהו\u0004 \u0005[שנקראים בשמותיהם]\u0006 — \u0003לא.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ריש לקיש ממה ששנינו בברייתא: \u0003גיטין הבאים ממדינת הים ועדים חתומים עליהם, אף על פי ששמותיהן\u0004 של העדים \u0003כשמות גוים\u0004 — \u0003כשירין, מפני שרוב ישראל שבחוצה לארץ שמותיהן כשמות גוים.\u0004 משמע שמכשירים אפילו בשמות שאינם שמות מובהקים של גויים!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא שונה, \u0003כדקתני טעמא\u0004 \u0005[כפי ששנה\u0006 במפורש מה \u0005הטעם]:\u0006 \u0003מפני שרוב ישראל שבחוצה לארץ שמותיהן כשמות גוים,\u0004 ולכן יש לשער שבדקו היטב בשעת חתימה, והחותמים היו יהודים. אבל בגיטין שבארץ ישראל יש לחשוש שהיו אלה גויים ואין מכשירים אלא בשמות גויים מובהקים. זה היה נוסח אחד של הדברים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שמה ששאל ריש לקיש את ר' יוחנן היה במקרה \u0003כי מתניתא בעא מיניה\u0004 \u0005[כמו בברייתא שאל אותו],\u0006 \u0003ופשט ליה ממתניתא\u0004 \u0005[ופתר לו\u0006 את הדבר \u0005מן הברייתא]\u0006 שגיטין הבאים מחוץ לארץ, אף על פי ששמות העדים החתומים כשמות גויים — כשרים.","\u0003האומר\u0004 לחבירו: \u0003\"תן גט זה לאשתי\" ו\u0004כן האומר: \u0003\"\u0004תן \u0003שטר שחרור זה לעבדי\", אם רצה\u0004 הנותן \u0003לחזור\u0004 בו \u0003בשניהן\u0004 לפני שיגיעו ליד האשה או העבד — \u0003יחזור,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: בגיטי נשים\u0004 יכול לחזור בו, \u0003אבל לא בשחרורי עבדים,\u0004 וטעמו של דבר: \u0003לפי שזכין\u0004 (זוכים) \u0003לאדם שלא בפניו,\u0004 ומשום כך מיד כשנותן את השטר לשליח כבר זכה בו השליח עבור העבד. \u0003ואין חבין לו,\u0004 לאדם, \u0003אלא בפניו,\u0004 וקבלת גט היא חוב לאשה, ולכן אין אדם אחר יכול לחייב אותה בקבלתו כשלא מרצונה, ואינה זוכה בגט בקבלתו של השליח.","וראיה לדבר ששחרור העבד הוא זכות לו, למרות שהעבד בזמן עבדותו נהנה מרבו ומקבל ממנו מזונות — משום שאין זכות זו של המזונות של העבד הכרחית, \u0003שאם ירצה\u0004 האדון \u0003שלא לזון את עבדו\u0004 — \u0003רשאי,\u0004 ונמצא שבעיקר העבדות יש חוב לעבד ואין בה צד זכות. \u0003ו\u0004אולם אם ירצה \u0003שלא לזון את אשתו\u0004 — \u0003אינו רשאי,\u0004 ולכן מצב הנישואין זכות הוא לאשה.","\u0003אמר להם\u0004 ר' מאיר: בכל זאת חוב הוא לעבד שהוא משתחרר, \u0003והרי הוא,\u0004 האדון, \u0003פוסל את עבדו מן התרומה\u0004 אם היה עבד של כהן, שעד עכשיו היה מותר לו לאכול תרומה, ועכשיו הוא נאסר בכך, \u0003כשם שהוא פוסל את אשתו\u0004 שהיתה ישראלית מלאכול בתרומה לאחר גירושיה! \u0003אמרו לו:\u0004 הטעם שהעבד מותר בתרומה אינו מכוח זכותו למזונות אלא \u0003מפני שהוא קניינו.\u0004","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב הונא ורב יצחק בר יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה, ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' ירמיה וקא\u0004 \u0005[והיה]\u0006 \u0003מנמנם\u0004 ובינתיים שוחחו השניים ביניהם, \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב הונא וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003שמע מינה מדרבנן\u0004 \u0005[למד מכאן מ\u0006דברי \u0005חכמים]\u0006 שאמרו שאין האדון יכול לחזור בו בשטר שחרור עבד אחר שכבר ניתן לשליח, מפני שכבר זכה השליח עבור העבד, הלכה כללית יותר: אדם סתם \u0003התופס\u0004 נכסים עבור \u0003בעל חוב\u0004 (מלווה) מנכסיו של הלווה, והרי זו, בודאי, זכות למלווה — \u0003קנה\u0004 בכך את הנכסים עבור בעל החוב. שהרי גם כאן השליח נעשה כתופס עבור העבד את שחרורו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יצחק בר יוסף:\u0004 האם אתה אומר כלל זה \u0003ואפילו במקום ש\u0004הוא \u0003חב לאחרים,\u0004 כלומר, גם במקרה שאם הוא לוקח מן החייב את מה שתופס ממנו — נמצא מחייב אחרים. כגון שהיו עוד בעלי חובות, וכשהוא תופס עבור אחד מהם, שוב אין לאחרים ממה לגבות את חובם, ונמצא שאחרים מפסידים על ידי תפיסתו זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","\u0003אדהכי איתער בהו\u0004 \u0005[בינתיים התעורר בהם,\u0006 בגללם\u0005]\u0006 \u0003ר' ירמיה,\u0004 שלא היה ישן ממש אלא מנמנם ושמע את דבריהם, ואז התעורר. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דרדקי\u0004 \u0005[ילדים,\u0006 תינוקות\u0005]!\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: התופס לבעל חוב במקום שחב לאחרים\u0004 — \u0003לא קנה. ואם תאמר: משנתינו,\u0004 שלכאורה מורה להיפך, שיכול לתפוס עבור העבד למרות שהוא גורם בכך הפסד לאדון!","יש להבדיל: כי \u0003כל האומר \"תנו\u0004 לפלוני \u0003\" כאומר \"זכו\u0004 עבורו \u0003\" דמי\u0004 \u0005[נחשב],\u0006 וכיון שאמר \"תנו שטר שחרור זה לעבד\" — הרי זה כמזכה לו, ויש לו דין אחר. אבל במקום שתופס מדעת עצמו ובכך הוא חב לאחרים — אין לכך תוקף.","\u0003אמר רב חסדא:\u0004 בבעיה זו של \u0003התופס לבעל חוב במקום שחב לאחרים, באנו למחלוקת ר' אליעזר ורבנן\u0004 \u0005[וחכמים].\u0006 ומהי מחלוקת זו? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי ש\u0004אינו עני ו\u0003ליקט את הפאה\u0004 בין העניים, \u0003ואמר: \"הרי זו,\u0004 מה שליקטתי, עבור \u0003פלוני\u0004 ה\u0003עני\", ר' אליעזר אמר: זכה לו\u0004 (עבורו), \u0003וחכמים אומרים:\u0004 לא זכה לו, אלא \u0003יתננו,\u0004 את מה שליקט, \u0003לעני הנמצא ראשון.\u0004 ולכאורה, ר' אליעזר הסבור שהמלקט את הפאה עבור העני זכה לו, למרות שהוא מפסיד בכך את העניים האחרים שנמצאים בשדה, ויכלו לזכות הם בפאה זו סובר שהתופס לבעל חוב במקום שחב לאחרים — קנה. וחכמים סוברים שלא.","\u0003אמר\u0004 \u0003אמימר, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא:\u0004"],["\u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא\u0004 זו \u0003היא\u0004 נקודת המחלוקת בין ר' אליעזר וחכמים. ובשני אופנים; ראשית, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 שזכה לעני בפאה \u0003אלא\u0004 מפני הטעם \u0003דמיגו דאי בעי מפקר להו לנכסיה והוי\u0004 \u0005[שמתוך שאם היה\u0006 המלקט \u0005רוצה היה\u0006 יכול \u0005להפקיר את נכסיו והיה\u0006 נעשה\u0005]\u0006 בכך \u0003עני וחזי ליה\u0004 \u0005[ו\u0006אז \u0005היה ראוי לו]\u0006 מה שליקט, \u0003ומיגו דזכי ליה לנפשיה זכי לחבריה\u0004 \u0005[ומתוך ש\u0006הוא יכול \u0005לזכות לעצמו\u0006 יכול \u0005לזכות\u0006 גם \u0005עבור חבירו],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בתופס לבעל חוב, שהתופס אינו יכול לתפוס נכסים אלו לעצמו — \u0003לא\u0004 שמענו שהוא סבור שיכול לתפוס במקום שמחייב אחרים.","ועוד יש לחלק לצד האחר: \u0003ועד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אומרים חכמים שם]\u0006 שאינו יכול לזכות עבור העני \u0003אלא\u0004 משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תלקט לעני\"\u0004 (ויקרא כג, כב), ודרשו חכמים: \u0003לא תלקט לו לעני,\u0004 אלא העני ילקט בעצמו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במקרה של תופס לבעל חוב, שאין גזירת הכתוב על כך — \u0003לא\u0004 שמענו לשיטתם שאין הוא קונה. ונמצא שאין מחלוקת ר' אליעזר וחכמים תלויה במחלוקת בדין התופס לבעל חוב במקום שחב לאחרים.","אגב כך שואלים: לפי פירוש זה \u0003ור' אליעזר, האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"לא תלקט\"\u0004 — \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 כיצד מבין הוא אותו? שהרי חכמים דרשוהו כשיטתם שאין לתפוס פאה לעני, וכיצד דורש הוא אותו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא \u0005אותו]\u0006 \u0003להזהיר\u0004 (לחייב) \u0003לעני על שלו,\u0004 שאם היה לעני שדה משלו, אינו רשאי ללקט בעצמו את הפאה, ואינו יכול לומר שמתוך שהוא עני יקח אותה לעצמו.","שנינו במשנה \u0003שאם ירצה\u0004 האדון \u0003שלא לזון\u0004 את עבדו — רשאי. ומעירים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003יכול הרב\u0004 (האדון) \u0003לומר לעבד \"עשה עמי\u0004 (עבוד למעני) \u0003ואיני זנך\".\u0004","ודוחים: משם אין ראיה, כי \u0003הכא\u0004 \u0005[כאן],\u0006 במשנתנו, \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 — במקרה ש\u0003אמר ליה\u0004 \u0005[לו],\u0006 לעבד \u0003\"צא מעשה ידיך למזונותיך\".\u0004 כלומר, אני איני מפרנס אותך אלא אתה תעבוד ותרוויח בעצמך את מזונותיך. אבל לא למדנו מכאן שיכול האדון גם להכריח את העבד לעבוד עבורו וגם לא להאכיל אותו.","ומקשים: אם כן \u0003דכוותה\u0004 \u0005[כיוצא בו]\u0006 יש לפרש במשנתנו ל\u0003גבי אשה\u0004 — ש\u0003אמר לה \"צאי מעשה ידיך במזונותיך\",\u0004 שאינו רשאי לפטור עצמו מחובתו לפרנסה על ידי ויתור על מעשה ידיה, ואולם \u0003אשה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 הרי ודאי שמותר לעשות הסכם כזה עם אשתו, ונמצא שגם לגבי האשה אין הגירושין חובה לה בדבר זה יותר מאשר לעבד! ומשיבים: \u0003אשה\u0004 שמזכירים במשנתנו — הרי זה מדובר \u0003ב\u0004ש\u0003לא ספקא\u0004 \u0005[מספקת]\u0006 במעשי ידיה את מזונותיה, ואז אין הבעל יכול לומר לה דבר זה.","ומקשים: אם כן \u0003עבד\u0004 שבמשנתנו \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר לכאורה \u0003בדלא ספיק\u0004 \u0005[בשאינו מספק],\u0006 שאינו מסוגל לפרנס את עצמו, ובכל זאת יכול אדונו לומר לו \"איני זנך\", והרי זה כ\"עשה עמי ואיני זנך\", ומשיבים: \u0003עבדא דנהום כרסיה לא שויא, למריה ולמרתיה למאי מיתבעי\u0004 \u0005[עבד\u0006 כזה \u0005שאת\u0006 ה\u0005לחם\u0006 שמכניס ל\u0005כריסו אינו שווה, לאדונו ולגבירתו למה\u0006 הוא \u0005נצרך]?\u0006 שוודאי קונים עבד שעבודתו תספיק גם למזונו וליותר מכן, שאם עבודתו אינה מספיקה אפילו כדי מזונותיו, לשם מה צריכים הם אותו? ועל כן אין אנשים מחזיקים עבד כזה שלא יספיקו מעשה ידיו למזונותיו, ולא עליו מדברת המשנה. אבל אשה — חובה עליו לזונה, ואין נישואיה תלויים בכך שיכולה לפרנס את עצמה במעשה ידיה. ואם כן, אין להוכיח ממשנתנו שיכול האדון לומר לעבד \"עשה עמי ואיני זנך\".","ומציעים ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003עבד ש\u0004הרג בשגגה ו\u0003גלה לערי מקלט\u0004 — \u0003אין רבו חייב לזונו, ולא עוד אלא שמעשה ידיו\u0004 שהוא עושה שם — שייכים \u0003לרבו. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003יכול הרב לומר לעבד \"עשה עמי ואיני זנך\"!\u0004 ודוחים גם כאן: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — כגון ש\u0003אמר לו \"צא מעשה ידיך למזונותיך\".\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אמר לו, \u0003מעשה ידיו אמאי\u0004 \u0005[מדוע]\u0006 שייכים \u0003לרבו?\u0004 הרי לפי מה שאמרנו הרי התנה אתו רבו שיפרנס את עצמו! ומשיבים: מדובר פה \u0003להעדפה,\u0004 כלומר, שאם הוא עובד ומרוויח יותר מכדי מזונותיו, שייך העודף הזה לאדון.","ותוהים: \u0003העדפה, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאיליו\u0005]\u0006 שהיא שייכת לאדון, הרי שלו הוא העבד! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003כיון דכי לית ליה לא יהיב ליה\u0004 \u0005[שכאשר אין לו\u0006 מספיק \u0005אין\u0006 האדון \u0005נותן לו]\u0006 כדי להשלים לצורכו, ואם כן \u0003כי אית ליה\u0004 \u0005[כאשר יש לו]\u0006 עודף על ידי עבודתו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לישקול מיניה\u0004 \u0005[יקח ממנו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת העודף שייך לאדון.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומדוע שונה]\u0006 הדבר בעבד שגלה \u0003לערי מקלט\u0004 שבו דווקא נאמר דבר זה? הרי לשיטה זו הוא הדין בכל עבד ובכל מקום! ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שכיון שנאמר במי שגולה לעיר מקלט \u0003\"\u0004ונס אל אחת הערים האל \u0003וחי\"\u0004 (דברים ד, מב), שמשמיע הכתוב שצריך לדאוג באופן מיוחד לחייו, ולפי זה יכולים היינו לפרש: \u0003עביד ליה חיותא טפי\u0004 \u0005[עשה,\u0006 תן לו, \u0005חיות יתירה],\u0006 ויזכה העבד במה שמעדיף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין בכך חובה מיוחדת, אף שהוא הדין בכל עבד.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003אבל אשה שגלתה לערי מקלט\u0004 — \u0003בעלה חייב במזונותיה, מכלל\u0004 הדברים אתה למד כי מדובר באופן ש\u0003לא אמר לה\u0004 \"צאי מעשה ידיך במזונותיך\", ולכן חייב במזונותיה, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003אמר לה בעלה\u0004 כך, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003חייב\u0004 במזונותיה?","\u0003ומדסיפא\u0004 \u0005[ומכיון שבסופה]\u0006 של הברייתא מדובר במקרה ש\u0003לא אמר לה,\u0004 אלא בסתם, אם כן \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילתה]\u0006 ודאי \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר במקרה ש\u0003לא אמר ליה\u0004 \u0005[לו],\u0006 לעבד \"צא מעשה ידיך במזונותיך\", אלא בסתם, שאם לא כן מה טעם להשוואה בין הדברים!","ודוחים: \u0003לעולם\u0004 תפרש ש\u0003אמר ליה\u0004 \u0005[לו,\u0006 לעבד\u0005],\u0006 \"צא מעשה ידך למזונותיך\" ואמר כמו כן גם לאשה, \u0003ו\u0004אולם ב\u0003אשה\u0004 מדובר \u0003בדלא ספקה\u0004 \u0005[בשאינה מספקת].\u0006","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה],\u0006 בהמשכה של אותה ברייתא: \u0003ואם אמר לה \"צאי מעשה ידיך במזונותיך\"\u0004 — \u0003רשאי, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבתחילה]\u0006 מדובר באופן ש\u0003לא אמר לה!\u0004 ודוחים: \u0003הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר],\u0006 כך יש לפרש: \u0003ואם מספקת, ואמר לה: \"צאי מעשה ידיך במזונותיך\"\u0004 — \u0003רשאי.\u0004","ושואלים: \u0003מספקת, מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר\u0006 בכך\u0005]?\u0006 הרי דין זה שווה בכל אשה, ולאו דווקא בזו שגולה לעיר מקלט! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 הרי נאמר: \u0003\"כל כבודה בת מלך פנימה\"\u0004 (תהלים מה, יד), ואולי משום כך צריך הבעל לדאוג דווקא בעיר מקלט שהאשה לא תעשה עבודה בחוץ, אלא רק מלאכה שעושה בבית, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין קפידה בדבר, ואף בעיר מקלט יכול לומר לה דבר זה.","לעצם הבעיה אם יכול הרב שלא לפרנס את עבדו למרות שהוא עובד עבורו, מציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שדבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 בנושא זה, ששנינו, \u0003רבן שמעון בן גמליאל אומר: יכול העבד לומר לרבו בשני\u0004 (בשנות) \u0003בצורת: \"או פרנסני\u0004 משלך, \u0003או הוציאני לחירות\". וחכמים אומרים: הרשות ביד רבו\u0004 להשאירו ברשותו ולא לפרנסו.","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר: יכול\u0004 האדון לומר לעבדו שיעבוד בשבילו ולא יפרנסנו, וכן אינו חייב לשחררו בשל כך, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל\u0005]\u0006 \u0003סבר: אינו יכול\u0004 ולכן הוא צריך לשחררו?!","על כך תוהים: \u0003ותיסברא\u0004 \u0005[וכי יכול אתה לסבור כך]\u0006 שבדבר זה הם חולקים? הלא \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"או פרנסני או הוציאני לחירות\"\u0004 אינו מתאים כאן, ובמקומו \u0003\"או פרנסני או תן לי מעשה ידי בפרנסתי\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003ועוד:\u0004 אם זוהי השאלה הכללית, אם כן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר שמדובר דווקא \u0003בשני בצורת?\u0004 הרי אותה מחלוקת יכולה להיות בכל זמן אחר!","\u0003אלא\u0004 יש לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה ש\u0003אמר לו\u0004 האדון לעבד \u0003\"צא מעשה ידיך למזונותיך\", ובשני בצורת לא ספק\u0004 \u0005[אין\u0006 העבד \u0005יכול לספק]\u0006 לפרנסה לעצמו בעבודתו, כיון שהמחירים גבוהים ואין שכר עבודתו מספיק למזונותיו.","\u0003רבן שמעון בן גמליאל סבר:\u0004 יכול העבד לומר לאדון: \u0003או פרנסני או הוציאני לחירות, כי היכי דחזו לי אינשי ומרחמין\u0004 \u0005[כדי שיראו אותי אנשים\u0006 שאין מי שמפרנסני \u0005וירחמו]\u0006 \u0003עלי\u0004 ויסייעו בידי. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 שאין זה נימוק לשחרר את העבד, כי \u0003מאן דמרחם אבני חרי, אעבד נמי רחומי מרחם\u0004 \u0005[מי שמרחם על בני חורין, על עבד גם כן מרחם]\u0006 ואם כן, אין סיבה לעבד להשתחרר כדי שיעזרו לו אנשים. ואם כן, אין מכאן ראיה שיש מי שסבור שיכול האדון לומר לעבדו \"עשה עמי ואיני זנך\".","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה ממה ש\u0003אמר רב: המקדיש ידי עבדו,\u0004 שכל מלאכה שיעשה נעשית הקדש, ונמצא שהעבד אינו יכול לעבוד עבור עצמו, \u0003אותו העבד לוה ואוכל, ו\u0004לאחר מכן \u0003עושה\u0004 מלאכה \u0003ופורע\u0004 עבור מה שלווה. על כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003יכול הרב לומר לעבד \"עשה עמי ואיני זנך\"!\u0004 שהרי האדון שלל מן העבד את יכולתו לעבוד עבור עצמו, ובכל זאת אינו צריך לפרנס אותו.","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004מקרה שהאדון \u0003מעלה\u0004 (מספק) \u0003לו מזונות.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003למאי\u0004 \u0005[למה]\u0006"],["\u0003לוה ואוכל?\u0004 והרי אדוניו מפרנס אותו! ומשיבים: מדובר כאן \u0003להעדפה\u0004 שהוא רוצה אוכל נוסף.","ומקשים: אם כן, \u0003ולימא ליה\u0004 \u0005[ויאמר לו]\u0006 \u0003הקדש: עד השתא סגי\u0004 \u0005[עכשיו היה מספיק]\u0006 \u0003לך בלא העדפה והשתא נמי תיסגי\u0004 \u0005[ועכשיו גם כן יהיה מספיק]\u0006 \u0003לך בלא העדפה\u0004 ומדוע דווקא עכשיו רוצה אתה יותר? ויחול ההקדש גם על זה! ומשיבים: \u0003הקדש גופיה\u0004 \u0005[עצמו]\u0006 \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 שיעבוד העבד ויאכל \u0003כי היכי דלשבח עבדיה\u0004 \u0005[כדי שיושבח עבדו]\u0006 על ידי אכילתו היתירה.","על עצם הענין הזה שאמרנו שהעבד \u0003עושה ופורע,\u0004 תוהים: כיצד יכול הוא לעשות זאת, הלא \u0003קמא קמא קדיש ליה\u0004 \u0005[ראשון ראשון\u0006 שהוא עושה מיד \u0005נעשה לו קדוש],\u0006 שהרי ידיו מוקדשות לשמים, ואם כן, כיצד יכול הוא לפרוע? ומשיבים: מדובר כאן כשהעבד עושה \u0003בפחות פחות משוה פרוטה\u0004 ואין הקדש חל על פחות משווה פרוטה, ובסכומים הקטנים הללו הוא יכול לפרוע מעט מעט את חובו.","ומעירים לפרש את דברי רב שההקדש חל על ידיו של העבד דווקא אם מעלה לו רבו מזונות: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 ש\u0003אמר רב: המקדיש ידי עבדו\u0004 — \u0003אותו העבד עושה ואוכל, דאי\u0004 \u0005[שאם]\u0006 \u0003לא עבדא\u0004 \u0005[העבד]\u0006 עצמו \u0003מאן פלח ליה\u0004 \u0005[מי יעבוד לו,\u0006 בשבילו\u0005]\u0006 ומה יאכל? ומשמע מכאן שלדעת רב אין ההקדש חל על ידיו של העבד.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שהלכה \u0003הך\u0004 \u0005[זו]\u0006 שאמר רב שהעבד לווה ופורע, עוסקת \u0003ב\u0004זמן שאדונו \u0003מעלה\u0004 לו מזונות \u0003ו\u0004הרי זה משום ש\u0003אינו יכול\u0004 לומר לו שיעשה ולא יאכל, \u0003והא\u0004 \u0005[ו\u0006אילו הלכה \u0005זו]\u0006 \u0003בשאינו מעלה\u0004 לו רבו מזונות, ולכן אינו יכול להקדיש את ידי העבד — \u0003שפיר\u0004 \u0005[יפה],\u0006 ואין שתי האימרות של רב חלוקות ביניהן.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שגם \u0003הך\u0004 \u0005[\u0006ההלכה \u0005ההיא]\u0006 מדברת \u0003בשאינו מעלה\u0004 לו רבו מזונות, \u0003ו\u0004הקדשו חל משום ש\u0003יכול\u0004 לומר לו שיעשה ולא יאכל, האם יש מקום לנימוק \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא עבדא\u0004 \u0005[העבד]\u0006 עצמו \u0003מאן פלח ליה\u0004 \u0005[מי יעבוד לו]?\u0006 \u0003מאן דבעי ניפלחיה\u0004 \u0005[מי שרוצה שיעבוד לו,\u0006 בשבילו\u0005],\u0006 שהרי אמרנו שהאדון יכול לומר לו שיתפרנס מן הצדקה!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שלדעת רב \u0003אינו יכול\u0004 לומר לעבדו שיעבוד עבורו והוא לא יפרנס אותו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שיטה אחרת באותה בעיה, ש\u0003אמר ר' יוחנן: הקוטע יד עבדו של חבירו\u0004 — \u0003נותן שבתו\u0004 (פיצוי עבור מה שהעבד שובת ממלאכה כתוצאה מהפגיעה בו) \u0003ו\u0004דמי \u0003רפואתו\u0004 של העבד \u0003לרבו, ואותו העבד\u0004 שאינו יכול לעבוד \u0003ניזון מן הצדקה. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003יכול הרב לומר לעבד \"עשה עמי ואיני זנך\",\u0004 שאם לא כן מדוע האדון נוטל דמי שבתו, כלומר, דמי מעשי ידיו של העבד, ועם זה ניזון הלה מן הצדקה?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004זמן שרבו \u0003מעלה לו מזונות.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ניזון\u0004 הוא \u0003מן הצדקה?\u0004 הרי יש לו מזונות! ומשיבים: \u0003להעדפה,\u0004 לדברים שמעבר למזונות שמקציב לו האדון.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"ניזון\u0004 מן הצדקה \u0003\"\u0004שמשמעה מזונות בכדי צורכו בלבד, אינה מדוייקת, אלא \u0003\"מתפרנס\u0004 מן הצדקה \u0003\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שלדעת ר' יוחנן \u0003יכול\u0004 הרב לומר לעבדו \"עשה עמי ואיני זנך\". ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא. כיון שהזכרנו את ההלכה הזו, דנים בה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003נותן שבתו ורפואתו לרבו.\u0004 ותוהים: \u0003שבתו, פשיטא\u0004 \u0005[פשוט]\u0006 הוא שכך הדין, שהרי האדון מפסיד מכך שהעבד אינו עובד! ומשיבים: \u0003רפואתו איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005]\u0006 שהיא לרבו.","ומקשים: ואכן מדוע דמי רפואתו לרבו? הרי \u0003רפואתו דידיה\u0004 \u0005[שלו]\u0006 \u0003היא, דבעי איתסויי ביה\u0004 \u0005[ש\u0006הרי הוא \u0005צריך להתרפא בה]\u0006 ולמה יתנה לרבו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאמדוה\u0004 \u0005[שאמדוהו],\u0006 העריכו הרופאים שהמכה או הפציעה הזו צריכה להתרפא \u0003לחמשא יומי\u0004 \u0005[בחמישה ימים],\u0006 \u0003ועבדו ליה סמא חריפא ואתסי בתלתא יומי\u0004 \u0005[ועשו לו סם חריף והתרפא בשלושה ימים]\u0006 במקום חמישה, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003צערא\u0004 \u0005[הצער]\u0006 שהוא סבל על ידי הסם החריף והוזיל את דמי הריפוי — \u0003דידיה\u0004 \u0005[שלו,\u0006 של העבד\u0005]\u0006 \u0003הוא,\u0004 ומשום כך יהא מותר דמי הריפוי של העבד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא, שאף דמים אלו שייכים לאדון ולא לעבד.","על הדיון במשנתנו בין ר' מאיר וחכמים \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' אלעזר, אמרנו לו למאיר: והלא זכות הוא לעבד שיוצא מתחת ידי רבו לחירות! אמר לנו: חוב הוא לו,\u0004 ומדוע? \u0003שאם היה עבד כהן\u0004 — \u0003פוסלו\u0004 על ידי כך \u0003מן\u0004 אכילת \u0003התרומה. אמרנו לו: והלא מה אם ירצה\u0004 הרב \u0003שלא לזונו ושלא לפרנסו,\u0004 הלא \u0003רשאי\u0004 הוא. ואם כן בעצם אין העבד מפסיד דבר בזה ששוחרר!","\u0003אמר לנו:\u0004 למרות זאת, אף אם יכול האדון שלא לזונו, עדיין רשאי העבד לאכול תרומה, \u0003ומה אילו עבד כהן\u0004 אפילו \u0003שברח\u0004 מרבו, או \u0003אשת כהן שמרדה על בעלה\u0004 (מסרבת למלא התחייבותיה כאשת איש) — \u0003הלא\u0004 בכל זאת \u0003אוכלין בתרומה\u0004 ממקום אחר, אף אם לא משל הבעל, \u0003ו\u0004אולם \u0003זה,\u0004 עבד ששיחררו, \u0003אינו אוכל\u0004 כלל מן התרומה וגם לא משל אחרים. \u0003אבל\u0004 גט \u0003אשה\u0004 — \u0003חוב הוא לה, שכן פסלה מן התרומה ומפסידה מן המזונות.\u0004","על דברי הברייתא הזו תוהים: \u0003מאי קאמרו ליה, ומאי קא מהדר להו\u0004 \u0005[מה אמרו לו\u0006 חכמים לר' מאיר, \u0005ומה\u0006 הוא \u0005החזיר,\u0006 השיב \u0005להם]?\u0006 כלומר, נראים הדברים שאינם מדברים באותו נושא, ואין פה שאלה ותשובה באותו ענין. ומסבירים: \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 ר' מאיר: \u0003השבתוני על המזונות,\u0004 ואמרתם לי שהאדון אינו חייב לפרנס את העבד, \u0003מה תשיבוני על התרומה?\u0004","\u0003וכי תימרו\u0004 \u0005[ואם תאמרו],\u0006 \u0003אי בעי זריק ליה גיטא ופסיל ליה\u0004 \u0005[אם רוצה\u0006 האדון \u0005זורק לו שטר\u0006 שיחרור בתוך ארבע אמות שלו \u0005ופוסל אותו\u0006 בכך\u0005],\u0006 אולם במקרה כזה אף לעבד יש עצה: \u0003שביק ליה ועריק ואזיל לעלמא\u0004 \u0005[יעזוב אותו,\u0006 את אדונו, \u0005ויברח ויילך לעולם]\u0006 ולא יניח לאדונו לשחררו בעל כרחו, והוא ימשיך להתפרנס מן התרומה;"],["והוא שאמר להם: \u0003ומה אילו עבד כהן שברח\u0004 \u0003ו\u0004כן \u0003אשת כהן שמרדה על בעלה הלא אוכלים בתרומה, ו\u0004אילו \u0003זה,\u0004 עבד ששיחרר אותו אדונו, \u0003אינו אוכל,\u0004 והרי זה איפוא חוב הוא לו מה ששיחררו האדון.","ושואלים: אם כן, \u0003שפיר קאמר להו\u0004 \u0005[יפה אמר להם]\u0006 ר' מאיר! ומה עונים חכמים על כך? \u0003אמר רבא: היינו דקא מהדרי ליה במתניתין\u0004 \u0005[זהו\u0006 מה \u0005ש\u0006הם \u0005השיבו\u0006 ואמרו \u0005לו במשנתנו]:\u0006 \u0003מפני שהוא קנינו.\u0004 וכך יש להבין את דבריהם: \u0003דאי בעי\u0004 \u0005[שאם ירצה]\u0006 האדון לפסול את עבדו מזכותו לאכילת תרומה, הרי גם אם יברח העבד יכול האדון לעשות כן בדרך אחרת — \u0003שקיל\u0004 \u0005[יטול]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003מישראל\u0004 תמורת העבד \u0003ופסיל ליה כל היכא דאיתיה\u0004 \u0005[ופוסל אותו\u0006 מלאכול בתרומה \u0005בכל מקום ש\u0006הוא \u0005נמצא].\u0006","ושואלים: \u0003ול\u0004דעת \u0003ר' מאיר, תינח\u0004 \u0005[נניח]\u0006 הסבר זה ביחס ל\u0003עבד כהן\u0004 שנפסל מן התרומה על ידי שיחרורו, אפשר לומר ששיחרורו חוב הוא לו, אבל \u0003עבד ישראל מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006 בזה\u0005]?\u0006 \u0003אמר ר' שמואל בר רב יצחק:\u0004 גם לעבד כזה יש הפסד בדבר, \u0003מפני\u0004 \u0003ש\u0004בזה שמשחררו \u0003מפסידו משפחה כנענית,\u0004 שעד עכשיו היה מותר בשפחה כנענית ועכשיו כשהוא משוחרר אסור בה.","ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003הרי\u0004 על ידי השיחרור \u0003הוא מתירו בבת חורין!\u0004 ומשיבים: מכל מקום \u0003עבדא בהפקירא ניחא ליה\u0004 \u0005[העבד ב\u0006חיי \u0005הפקר נוח לו]\u0006 ומעדיף הוא שפחה כנענית, כי \u0003זילא ליה, שכיחא ליה, פריצה ליה\u0004 \u0005[מזולזלת,\u0006 בזוייה היא \u0005לו,\u0006 בעיניו, \u0005מצויה\u0006 היא \u0005לו, פרוצה\u0006 היא \u0005לו,\u0006 עבורו\u0005]\u0006 ובת חורין אינה כזו, ומשום כך נמצא מפסיד את הנאותיו בשפחה, ולכן אין השיחרור נחשב זכות עבורו לדעת ר' מאיר.","\u0003האומר \"תנו גט זה לאשתי\",\u0004 או שאומר \u0003\"\u0004תנו \u0003שטר שחרור זה לעבדי\", ומת\u0004 — \u0003לא יתנו לאחר מיתה,\u0004 שאין גט או שטר שיחרור עבד חלים אלא מכוחו של האיש המקנה אותם, וכיון שמת — בטל כוחו, ובטלה גם השליחות מטעמו. אבל אם אמר \u0003\"תנו מנה\u0004 (מאה זוז) \u0003לאיש פלוני\", ומת\u0004 המצוה — \u0003יתנו לאחר מיתה.\u0004","\u0003אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 מה שאמרנו שיתנו מנה מכוח הציווי, ואף לאחר מות המצוה — \u0003והוא\u0004 דווקא \u0003ש\u0004אותן הזוזים שעליהם ציווה \u0003צבורין ומונחין בקרן זוית\u0004 בשעת הציווי.","ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה מקרה \u0005אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר פה \u0003ב\u0004אדם \u0003בריא\u0004 שציווה לתת את המנה, \u0003כי\u0004 \u0005[כאשר]\u0006 הנכסים \u0003צבורין מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא משך\u0004 המקבל, ואין אדם זוכה במיטלטלין ללא פעולה של קנין! \u0003ואלא\u0004 צריך אתה לומר שמדובר \u0003בשכיב מרע\u0004 שציוויו בדיבור בלבד מועיל, אם כן, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 למה דווקא\u0005]\u0006 צריך שיהיו הכספים \u0003צבורין?\u0004 והרי \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אין\u0004 הם \u0003צבורין נמי\u0004 \u0005[גם כן]\u0006 הוא הדין \u0003דהא קיימא לן\u0004 \u0005[שהרי מוחזק בידינו]\u0006 הכלל ש\u0003דברי שכיב מרע\u0004 המצווה לתת מנכסיו — \u0003ככתובים וכמסורין דמו\u0004 \u0005[נחשבים],\u0006 ואינם צריכים כל קנין אחר!","\u0003אמר רב זביד: לעולם\u0004 מדובר \u0003בבריא,\u0004 \u0003ו\u0004יש לפרש את הדבר \u0003כ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב,\u0004 האומר לחבירו: \u0003\"מנה לי בידך,\u0004 כלומר, אותו מנה שאתה חייב לי, \u0003תנהו לו לפלוני\",\u0004 אם היה הדבר \u0003במעמד שלשתן\u0004 — \u0003קנה\u0004 אותו פלוני. ואם כן מדובר שהיה הזוכה באותו מקום והנותן הורה לזה לשלם לו, וקנה הזוכה על ידי \"מעמד שלושתם\", ואין סוג כזה של קנין חל אלא בצבורים.","\u0003רב פפא אמר: לעולם\u0004 תפרש שמדובר \u0003בשכיב מרע, וכאידך\u0004 \u0005[וכ\u0006הלכה \u0005אחרת]\u0006 של \u0003רב,\u0004 ש\u0003אמר רב: שכיב מרע שאמר \"תנו מנה לפלוני מנכסי\",\u0004 אם אמר: \u0003\"\u0004תנו \u0003מנה זה\"\u0004 הנמצא באותו מקום — הרי \u0003נותנין,\u0004 ואם אמר \u0003\"מנה\" סתם\u0004 — \u0003אין נותנין,\u0004 ומדוע?","\u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא מנה קבור קאמר\u0004 \u0005[אמר],\u0006 שלא היתה כוונתו אלא למנה מסויים שאין אנו יודעים היכן הוא נמצא, ומנה אחר לא נתן. ומשום כך צריכים אנו לפרש את משנתנו במנה המונח במקום מוגדר (\"צבורים\") והמצוה מציין במפורש שאליו כוונתו (\"מנה זה\").","ומעירים: \u0003והלכתא\u0004 \u0005[והלכה ]\u0006 היא: \u0003לקבורה,\u0004 למנה קבור, \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 ושלא כדברי רב. ובבירור הענין שואלים: \u0003רב פפא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב\u0004 \u0003זביד\u0004 בפירוש דברי רב?"],["ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003רב פפא\u0004 שאם היה מדובר במשנתנו בהקנאה במעמד שלושתם, אין צורך להעמידה לדעת רב במעות צבורים דווקא, שכן לדעתו \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר רב\u0004 שניתן להקנות במעמד שלושתם — \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003במלוה\u0004 שבו אין מקנים מעות מסויימים, \u0003ולא שנא\u0004 \u0005[שונה]\u0006 \u0003בפקדון,\u0004 אלא בכלל אמר, ולכן אין הכרח שיהיו המעות צבורים, ומשום כך הוצרך רב פפא להסביר את דברי רב שמדובר במשנתנו בצבורים רק משום חשש למנה קבור.","ושואלים מצד שני: \u0003רב זביד מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב פפא\u0004 בפירוש דברי רב? ומשיבים: כי הוא סבור ש\u0003לא מיתוקמא מתניתין\u0004 \u0005[אין\u0006 אפשרות \u0005להעמיד\u0006 את \u0005משנתנו]\u0006 \u0003בשכיב מרע. ממאי\u0004 \u0005[ממה]\u0006 הוא מסיק דברים אלה? — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 בתחילת המשנה: \u0003האומר \"תנו גט זה לאשתי ושטר שחרור זה לעבדי\", ומת\u0004 — \u0003לא יתנו לאחר מיתה.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003מת\u0004 האיש, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה הדבר \u0003מחיים\u0004 — \u0003נותנין.\u0004 ונדייק עוד: אף בחייו של האיש, \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא כש\u0003אמר \"תנו\", הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אמר \"תנו\",\u0004 אלא אמר רק \"כתבו גט\" — \u0003אין נותנין.\u0004 \u0003ו\u0004אולם \u0003שכיב מרע\u0004 שאמר כגון זה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר \"תנו\"\u0004 אלא רק \"כתבו\" — בכל זאת \u0003נותנין\u0004 את הגט.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בראשונה היו אומרים: היוצא בקולר\u0004 (מעין שרשרת שעל הצוואר) שמוליכים בו את המחוייבים מיתה למלכות, \u0003ואמר \"כתבו גט לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו,\u0004 ואף שלא אמר במפורש \"תנו\", מכל מקום אנו מבינים שזו היתה כוונתו. \u0003חזרו לומר\u0004 שאותו דין קיים \u0003אף\u0004 ב\u0003המפרש\u0004 (היוצא לים) \u0003והיוצא בשיירא\u0004 לדרך רחוקה, שנותנים את הגט לאשה גם אם אמר הבעל רק \"כתבו\".","\u0003ר' שמעון שזורי אומר: אף המסוכן,\u0004 כלומר, אדם שנוטה למות. ואם כן, יוצא מכאן שמי שמסוכן = שכיב מרע, אינו צריך לומר \"תנו\", אלא די לו שיאמר \"כתבו\". ואילו ממשנתנו עולה שמדובר דווקא כשהוא אומר \"תנו\", ואם כן ודאי אין המשנה מדברת בשכיב מרע.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ומאן נימא לן דמתניתין\u0004 \u0005[ומי יאמר לנו שמשנתנו]\u0006 כדעת \u0003ר' שמעון שזורי היא? דלמא רבנן\u0004 \u0005[שמא\u0006 כשיטת \u0005חכמים]\u0006 \u0003היא\u0004 והם אינם מונים את המסוכן בין אלה שאין צורך שיאמרו \"תנו\"! ואם כן, אפשר לפרש יפה את המשנה אפילו בשכיב מרע, ואין מכאן הוכחה.","ודנים עתה \u0003גופא\u0004 \u0005[לגופו]\u0006 של אותו דבר ש\u0003אמר רב הונא אמר רב,\u0004 האומר לחבירו: \u0003\"מנה לי בידך תנהו לו לפלוני\",\u0004 אם היה זה \u0003במעמד שלשתן\u0004 — \u0003קנה\u0004 בכך אותו פלוני באותה שעה את המנה. \u0003אמר רבא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב\u0004 דווקא \u0003בפקדון,\u0004 כאשר בעל הפקדון מורה לשומר הפקדון להעביר את המטבעות המסויימים שברשותו לאדם אחר הנמצא אף הוא באותו מעמד, ואנו מחשיבים את פעולת הקנין כאילו נתבצעה. \u0003אבל במלוה\u0004 — \u0003לא,\u0004 שהרי ההלוואה אינה דבר מסויים שניתן להקנות אותו.","ורבא עצמו מוסיף, ובלשון שבועה: \u0003והאלהים! אמר רב: אפילו במלוה.\u0004 ומוסיפים: \u0003אתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 ש\u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003לוי\u0004 במפורש: האומר לחבירו \u0003\"מלוה לי בידך, תנהו לו לפלוני\",\u0004 אם היה זה \u0003במעמד שלשתן\u0004 — \u0003קנה.\u0004","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומהו טעם\u0006 הדבר\u0005],\u0006 מדוע באמת הוא קונה? \u0003אמר אמימר: נעשה\u0004 הלווה \u0003כאומר לו\u0004 למלווה \u0003בשעת מתן מעות\u0004 בזמן קבלת ההלוואה: בזה \u0003שעבדנא לך לדידך\u0004 \u0005[משועבד אני לך]\u0006 \u0003ולכל\u0004 מי \u0003דאתו מחמתך\u0004 \u0005[שבאים מכוחך]\u0006 ונעשה עתה זה המקבל במעמד שלושתם כבא כוחו של המלווה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: אלא מעתה,\u0004 לפי ההסבר שנתת לדבר, שהשיעבוד למקבל חל בזמן ההלוואה, אם \u0003הקנה\u0004 במעמד שלושתם \u0003לנולדים,\u0004 לאנשים ש\u0003לא הוו\u0004 \u0005[היו]\u0006 עדיין בעולם \u0003בשעת מתן מעות, הכי נמי דלא קנו\u0004 \u0005[כך גם כן\u0006 יהיה הדין \u0005שאינם קונים\u0006 המקבלים\u0005],\u0006 שהרי בשעה שנתן את הכסף ללווה לא היה הזוכה הזה קיים בעולם, ולא יכול היה הלווה להשתעבד לו.","ש\u0003אפילו ל\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 ש\u0003אדם מקנה\u0004 לחבירו \u0003דבר\u0004 אף \u0003שלא בא\u0004 עדיין אותו דבר \u0003לעולם, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים כשהוא מקנה \u0003לדבר ש\u0004כבר \u0003ישנו בעולם, אבל\u0004 להקנות \u0003לדבר שאינו בעולם\u0004 — בוודאי ש\u0003לא\u0004 יכול להקנות. ואולם כיון שרב אמר את דבריו בדרך כללית וללא הסתייגויות — משמע שדין ההקנייה של מעמד שלושתם חל בכל מקרה וגם על נולדים, ואינו תלוי בשיעבוד שבשעת מתן החוב!","\u0003אלא אמר רב אשי,\u0004 זהו טעמו של דבר:"]]};
